# --- Zerodha Automation API ---
zerodha_sessions = {}   # api_key -> {connected, token}
zerodha_orders   = []   # order log

# Persist the Kite session (api_secret + access_token) to disk so a server restart
# within the same trading day keeps you logged in. Kite tokens expire ~6am IST, so
# we reload only if saved within the last ~day; a dead token is caught by /verify.
_ZD_SESSION_FILE = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'zerodha_session.json')
_ZD_SESSION_TTL  = 86400

def _zd_save_sessions():
    try:
        import json as _j, time as _t
        with open(_ZD_SESSION_FILE, 'w', encoding='utf-8') as f:
            _j.dump({'ts': int(_t.time()), 'sessions': zerodha_sessions}, f)
    except Exception:
        pass

def _zd_load_sessions():
    try:
        import json as _j, time as _t
        if not os.path.exists(_ZD_SESSION_FILE):
            return
        with open(_ZD_SESSION_FILE, encoding='utf-8') as f:
            data = _j.load(f)
        if int(_t.time()) - int(data.get('ts', 0)) < _ZD_SESSION_TTL:
            for k, v in (data.get('sessions') or {}).items():
                if isinstance(v, dict) and v.get('access_token'):
                    zerodha_sessions[k] = v
    except Exception:
        pass

_zd_load_sessions()

@app.route('/api/zerodha/connect', methods=['POST'])
@login_required
def zerodha_connect():
    data = request.json or {}
    api_key      = data.get('api_key', '').strip()
    api_secret   = data.get('api_secret', '').strip()
    access_token = data.get('access_token', '').strip()
    if not (api_key and access_token):
        return jsonify({'success': False, 'error': 'API key and access token required'}), 400
    # Store credentials (actual KiteConnect integration goes here)
    zerodha_sessions[api_key] = {
        'api_secret': api_secret,
        'access_token': access_token,
        'connected': True
    }
    _zd_save_sessions()   # persist so a restart within the day keeps the session
    return jsonify({'success': True, 'message': 'Connected to Zerodha'})

@app.route('/api/zerodha/verify', methods=['GET'])
@login_required
def zerodha_verify():
    """Real connection check — confirms the stored Kite access_token still works
    by hitting /user/profile. Returns {connected: bool, user?}."""
    import json as _json
    api_key = request.args.get('api_key', '').strip()
    if not api_key or api_key not in zerodha_sessions:
        return jsonify({'connected': False, 'error': 'no server session'})
    access_token = zerodha_sessions[api_key].get('access_token', '')
    if not access_token:
        return jsonify({'connected': False, 'error': 'no access token'})
    try:
        req = _zd_urllib.Request('https://api.kite.trade/user/profile',
            headers={'X-Kite-Version': '3', 'Authorization': 'token {}:{}'.format(api_key, access_token),
                     'User-Agent': 'Mozilla/5.0'}, method='GET')
        with _kite_urlopen(req, timeout=12) as resp:
            data = _json.loads(resp.read().decode('utf-8') or '{}')
        if data.get('status') == 'success':
            u = data.get('data', {}) or {}
            return jsonify({'connected': True, 'user': u.get('user_name') or u.get('user_id') or ''})
        return jsonify({'connected': False, 'error': data.get('message', 'invalid session')})
    except Exception as e:
        return jsonify({'connected': False, 'error': str(e)[:140]})

@app.route('/api/zerodha/order', methods=['POST'])
@login_required
def zerodha_order():
    """Place a Zerodha order.

    Honors a `dry_run` flag (default true if omitted) — when true, the request
    is logged only and no real order reaches Kite. When false, posts to
    api.kite.trade/orders/regular using the session's access token.

    Body params (JSON):
        api_key (str): identifies the session in zerodha_sessions.
        symbol (str):  Kite tradingsymbol (e.g. CRUDEOILM26JUNFUT, NIFTY26JUN24000CE).
        exchange (str):NSE | BSE | NFO | BFO | MCX | CDS | BCD (default NSE).
        side (str):    BUY | SELL.
        qty (int):     quantity.
        product (str): MIS | NRML | CNC. Defaults: NRML for derivatives, MIS otherwise.
        order_type (str): MARKET | LIMIT | SL | SL-M (default MARKET).
        algo/score: free-form metadata stored in the log.
        dry_run (bool): if true (default), don't actually call Kite.
    """
    import urllib.parse as _up, urllib.error as _ue, json as _json
    data = request.json or {}
    api_key      = data.get('api_key', '').strip()
    symbol       = data.get('symbol', '').strip()
    exchange     = (data.get('exchange') or '').strip().upper()
    side         = data.get('side', '').upper()
    qty          = int(data.get('qty', 1) or 1)
    order_type   = (data.get('order_type') or 'MARKET').strip().upper()
    product      = (data.get('product') or '').strip().upper()
    # Slippage cap for MARKET orders, in % of LTP. Kite Connect rejects MARKET
    # orders without this set (the API won't let bots fire blind market orders).
    # Default 3% — narrow enough to be safe, wide enough to fill in normal
    # market conditions. User can override per-order via the request body.
    # NB: cannot do `float(... or 5.0)` here — `0 or 5.0` is 5.0 (0 is falsy).
    # That would silently override "Market Order = no MP" (mp=0) requests.
    _mp_raw = data.get('market_protection')
    try:
        market_protection = float(_mp_raw) if _mp_raw is not None else 5.0
    except (TypeError, ValueError):
        market_protection = 5.0
    limit_price  = data.get('price')   # for LIMIT/SL orders
    trigger_price = data.get('trigger_price')   # for SL/SL-M
    algo         = data.get('algo', '')
    score        = data.get('score', 0)
    dry_run      = data.get('dry_run', True)  # default to dry-run for safety

    if api_key not in zerodha_sessions:
        return jsonify({'success': False, 'error': 'Not connected (open Zerodha Login)'}), 403
    if side not in ('BUY', 'SELL'):
        return jsonify({'success': False, 'error': 'Invalid side'}), 400
    if not symbol:
        return jsonify({'success': False, 'error': 'Missing symbol'}), 400

    # Auto-derive exchange from instrument lookup when missing.
    # Common case: rules created before the Kite-tab metadata wiring don't
    # carry an exchange, so we'd default to NSE and get back Kite's
    # "instrument has expired or does not exist" 400 for any MCX/NFO contract.
    if not exchange:
        sym_u = symbol.upper()
        candidates = []
        for src in (_load_kite_all_instruments() or [], _load_csv_instruments() or []):
            candidates.extend([r for r in src if (r.get('symbol') or '').upper() == sym_u])
            if candidates:
                break
        # Prefer established exchanges first (so duplicate MCX/NCO listings
        # snap to MCX, NFO over BFO, etc.)
        _prio = {'NSE':0, 'BSE':1, 'NFO':2, 'BFO':3, 'MCX':4, 'CDS':5, 'BCD':6, 'NCO':7}
        candidates.sort(key=lambda r: _prio.get((r.get('exchange') or '').strip().upper(), 99))
        if candidates:
            exchange = (candidates[0].get('exchange') or '').strip().upper()
        if not exchange:
            exchange = 'NSE'   # final fallback

    # Default product: derivatives use NRML, equities use MIS
    if not product:
        product = 'NRML' if exchange in ('NFO', 'BFO', 'MCX', 'CDS', 'BCD', 'NCO') else 'MIS'

    # Quantize LIMIT/SL prices to the instrument's tick size before logging
    # (so the dry-run preview matches what the live path would send).
    if order_type in ('LIMIT', 'SL', 'SL-M'):
        _tick = _get_instrument_tick(symbol, exchange)
        if order_type in ('LIMIT', 'SL') and limit_price is not None:
            limit_price = _quantize_to_tick(limit_price, _tick)
        if order_type in ('SL', 'SL-M') and trigger_price is not None:
            trigger_price = _quantize_to_tick(trigger_price, _tick)

    # Dry-run: log only, return a fake order id
    if dry_run:
        order_id = 'DRY-' + str(uuid.uuid4())[:6]
        entry = {
            'order_id': order_id, 'symbol': symbol, 'exchange': exchange,
            'side': side, 'qty': qty, 'product': product, 'order_type': order_type,
            'price': limit_price, 'trigger_price': trigger_price,
            'algo': algo, 'score': score, 'status': 'DRY-RUN',
            'timestamp': datetime.utcnow().isoformat()
        }
        zerodha_orders.append(entry)
        return jsonify({'success': True, 'orderId': order_id, 'order': entry, 'dry_run': True,
                        'sent_price': limit_price})

    # Real order via Kite Connect v3 REST API
    access_token = zerodha_sessions[api_key].get('access_token', '')
    if not access_token:
        return jsonify({'success': False, 'error': 'No access_token in server session — re-Connect'}), 403

    payload_d = {
        'tradingsymbol':    symbol,
        'exchange':         exchange,
        'transaction_type': side,
        'quantity':         qty,
        'product':          product,
        'order_type':       order_type,
        'validity':         'DAY',
    }
    # MARKET orders: attach market_protection only if the caller set a positive
    # value. When zero/omitted, the request goes bare to Kite as a true MARKET
    # order. Kite enforces MP on some exchanges (MCX in particular) and will
    # reject — that's the user's explicit choice when the "Market Order"
    # checkbox is ticked in the panel.
    if order_type == 'MARKET' and market_protection > 0:
        payload_d['market_protection'] = market_protection
    # LIMIT / SL orders need a price; SL / SL-M need a trigger.
    # Quantize to the instrument's tick size — Kite rejects any price that
    # isn't an exact multiple (MCX CRUDEOILM tick=1.00, NSE equity 0.05, etc.).
    _tick = _get_instrument_tick(symbol, exchange) if order_type in ('LIMIT', 'SL', 'SL-M') else 0
    if order_type in ('LIMIT', 'SL') and limit_price is not None:
        limit_price = _quantize_to_tick(limit_price, _tick)
        payload_d['price'] = limit_price
    if order_type in ('SL', 'SL-M') and trigger_price is not None:
        trigger_price = _quantize_to_tick(trigger_price, _tick)
        payload_d['trigger_price'] = trigger_price
    payload = _up.urlencode(payload_d).encode('utf-8')
    req = _zd_urllib.Request(
        'https://api.kite.trade/orders/regular',
        data=payload,
        headers={
            'X-Kite-Version': '3',
            'Authorization':  'token {}:{}'.format(api_key, access_token),
            'Content-Type':   'application/x-www-form-urlencoded',
            'User-Agent':     'Mozilla/5.0',
        },
        method='POST'
    )
    try:
        with _kite_urlopen(req, timeout=15) as resp:
            body = resp.read().decode('utf-8')
        resp_data = _json.loads(body) if body else {}
    except _ue.HTTPError as e:
        err_body = ''
        try:
            err_body = e.read().decode('utf-8')
        except Exception:
            pass
        # Try to parse Kite's structured error
        try:
            err_data = _json.loads(err_body)
            err_msg  = err_data.get('message', err_body[:300])
        except Exception:
            err_msg = err_body[:300] or str(e)
        # Include the order context so the user can see what was actually sent
        ctx_parts = ['{} {} qty={} exch={} prod={}'.format(side, symbol, qty, exchange, product),
                     'type=' + order_type]
        if order_type == 'MARKET' and market_protection > 0:
            ctx_parts.append('mp={}%'.format(market_protection))
        elif order_type == 'MARKET':
            ctx_parts.append('mp=none')
        if order_type in ('LIMIT', 'SL') and limit_price is not None:
            ctx_parts.append('price={}'.format(limit_price))
        return jsonify({
            'success': False,
            'error':   'Kite HTTP {}: {} (sent: {})'.format(e.code, err_msg, ' '.join(ctx_parts)),
            'sent':    payload_d
        })
    except Exception as e:
        return jsonify({'success': False, 'error': 'Kite request failed: {}'.format(e)})

    if resp_data.get('status') == 'success':
        order_id = resp_data.get('data', {}).get('order_id', '')
        entry = {
            'order_id': order_id, 'symbol': symbol, 'exchange': exchange,
            'side': side, 'qty': qty, 'product': product, 'order_type': order_type,
            'price': limit_price, 'trigger_price': trigger_price,
            'algo': algo, 'score': score, 'status': 'PLACED',
            'timestamp': datetime.utcnow().isoformat()
        }
        zerodha_orders.append(entry)
        return jsonify({'success': True, 'orderId': order_id, 'order': entry,
                        'sent_price': limit_price})
    return jsonify({'success': False, 'error': resp_data.get('message', 'Order rejected'), 'data': resp_data})

@app.route('/api/zerodha/orders', methods=['GET'])
@login_required
def zerodha_orders_list():
    return jsonify({'success': True, 'orders': zerodha_orders[-50:]})

@app.route('/api/zerodha/order_status', methods=['GET'])
@login_required
def zerodha_order_status():
    """Query Kite for the current status of an order. Used by the front-end
    a few seconds after placing an order to confirm whether it actually
    filled, sat as OPEN, was REJECTED, or CANCELLED.

    Query params:  api_key, order_id
    Returns:       {status, status_message, average_price, filled_quantity,
                    pending_quantity, exchange_order_id, ...}
    """
    import json as _json, urllib.parse as _up
    api_key  = request.args.get('api_key', '').strip()
    order_id = request.args.get('order_id', '').strip()
    if not api_key or api_key not in zerodha_sessions:
        return jsonify({'success': False, 'error': 'Not connected'}), 403
    if not order_id:
        return jsonify({'success': False, 'error': 'Missing order_id'}), 400
    access_token = zerodha_sessions[api_key].get('access_token', '')
    req = _zd_urllib.Request(
        'https://api.kite.trade/orders/' + _up.quote(order_id),
        headers={
            'X-Kite-Version': '3',
            'Authorization':  'token {}:{}'.format(api_key, access_token),
            'User-Agent':     'Mozilla/5.0',
        }, method='GET'
    )
    try:
        with _kite_urlopen(req, timeout=10) as resp:
            body = resp.read().decode('utf-8')
        data = _json.loads(body)
    except Exception as e:
        return jsonify({'success': False, 'error': 'Kite request failed: {}'.format(e)})
    if data.get('status') != 'success':
        return jsonify({'success': False, 'error': data.get('message', 'Kite error')})
    # Kite returns a list (history of state transitions) — last entry is current
    history = data.get('data', []) or []
    if not history:
        return jsonify({'success': False, 'error': 'No order found'})
    cur = history[-1]
    return jsonify({
        'success':            True,
        'order_id':           cur.get('order_id'),
        'status':             cur.get('status'),              # OPEN / COMPLETE / REJECTED / CANCELLED
        'status_message':     cur.get('status_message'),       # Kite's reason text
        'average_price':      cur.get('average_price'),
        'filled_quantity':    cur.get('filled_quantity'),
        'pending_quantity':   cur.get('pending_quantity'),
        'exchange_order_id':  cur.get('exchange_order_id'),
        'transaction_type':   cur.get('transaction_type'),
        'tradingsymbol':      cur.get('tradingsymbol'),
    })

@app.route('/api/zerodha/positions', methods=['GET'])
@login_required
def zerodha_positions():
    """Return current net positions from Kite, compressed to {symbol: net_qty}.

    The Automation panel polls this each tick to detect external exits
    (GTT triggers, manual square-off on Kite app, etc.) so it can reset
    in-memory position state and let entry rules fire again.
    """
    import json as _json
    api_key = request.args.get('api_key', '').strip()
    if not api_key or api_key not in zerodha_sessions:
        return jsonify({'success': False, 'error': 'Not connected', 'positions': {}})
    access_token = zerodha_sessions[api_key].get('access_token', '')
    if not access_token:
        return jsonify({'success': False, 'error': 'No access token', 'positions': {}})

    req = _zd_urllib.Request(
        'https://api.kite.trade/portfolio/positions',
        headers={
            'X-Kite-Version': '3',
            'Authorization': 'token {}:{}'.format(api_key, access_token),
            'User-Agent':    'Mozilla/5.0',
        }, method='GET'
    )
    try:
        with _kite_urlopen(req, timeout=15) as resp:
            body = resp.read().decode('utf-8')
        data = _json.loads(body) if body else {}
    except Exception as e:
        return jsonify({'success': False, 'error': 'Kite request failed: {}'.format(e), 'positions': {}})
    if data.get('status') != 'success':
        return jsonify({'success': False, 'error': data.get('message', 'Kite error'), 'positions': {}})
    positions = {}
    for p in (data.get('data', {}).get('net', []) or []):
        sym = p.get('tradingsymbol', '')
        if sym:
            try:
                positions[sym] = int(p.get('quantity', 0) or 0)
            except (TypeError, ValueError):
                positions[sym] = 0
    return jsonify({'success': True, 'positions': positions})

@app.route('/api/zerodha/gtt', methods=['POST'])
@login_required
def zerodha_gtt():
    """Place a GTT (Good Till Triggered) on Kite.

    Body params (JSON):
        api_key (str)
        tradingsymbol (str)
        exchange (str)
        trigger_type (str): 'single' | 'OCO' | 'two-leg'
        side (str): BUY | SELL  (the side of the resulting order)
        qty (int)
        ltp (float):           current last-traded-price for Kite's condition
        sl_price (float):      stop-loss trigger price (always required)
        target_price (float):  target trigger price (required for OCO)
        product (str):         default NRML for derivatives, CNC otherwise
        order_type (str):      default LIMIT (Kite GTTs only support LIMIT)
        dry_run (bool):        default True (log only, no Kite call)
    """
    import urllib.parse as _up, urllib.error as _ue, json as _json
    data = request.json or {}
    api_key      = data.get('api_key', '').strip()
    symbol       = data.get('tradingsymbol', '').strip()
    exchange     = (data.get('exchange') or '').strip().upper()
    trigger_type = (data.get('trigger_type') or 'single').strip()
    side         = data.get('side', '').upper()
    qty          = int(data.get('qty', 1) or 1)
    ltp          = float(data.get('ltp', 0) or 0)
    sl_price     = float(data.get('sl_price', 0)     or 0) if data.get('sl_price')     not in (None, '') else None
    target_price = float(data.get('target_price', 0) or 0) if data.get('target_price') not in (None, '') else None
    product      = (data.get('product') or '').strip().upper()
    order_type   = (data.get('order_type') or 'LIMIT').strip().upper()
    dry_run      = data.get('dry_run', True)

    if api_key not in zerodha_sessions:
        return jsonify({'success': False, 'error': 'Not connected'}), 403
    if side not in ('BUY', 'SELL'):
        return jsonify({'success': False, 'error': 'Invalid side'}), 400
    if not symbol or not exchange:
        return jsonify({'success': False, 'error': 'Missing tradingsymbol or exchange'}), 400
    if not product:
        product = 'NRML' if exchange in ('NFO', 'BFO', 'MCX', 'CDS', 'BCD', 'NCO') else 'CNC'

    gtt_type = 'two-leg' if trigger_type.upper() in ('OCO', 'TWO-LEG') else 'single'

    if gtt_type == 'single':
        if not sl_price:
            return jsonify({'success': False, 'error': 'sl_price required for single GTT'}), 400
        sl_q = _quantize_to_tick(sl_price, _get_instrument_tick(symbol, exchange))
        trigger_values = [sl_q]
        orders = [{
            'exchange': exchange, 'tradingsymbol': symbol,
            'transaction_type': side, 'quantity': qty,
            'order_type': order_type, 'product': product,
            'price': sl_q,
        }]
    else:
        if not sl_price or not target_price:
            return jsonify({'success': False, 'error': 'Both sl_price and target_price required for OCO'}), 400
        _tick = _get_instrument_tick(symbol, exchange)
        sl_q  = _quantize_to_tick(sl_price,     _tick)
        tg_q  = _quantize_to_tick(target_price, _tick)
        trigger_values = sorted([sl_q, tg_q])
        orders = [{
            'exchange': exchange, 'tradingsymbol': symbol,
            'transaction_type': side, 'quantity': qty,
            'order_type': order_type, 'product': product,
            'price': trigger_values[0],
        }, {
            'exchange': exchange, 'tradingsymbol': symbol,
            'transaction_type': side, 'quantity': qty,
            'order_type': order_type, 'product': product,
            'price': trigger_values[1],
        }]

    condition = {
        'exchange': exchange, 'tradingsymbol': symbol,
        'trigger_values': trigger_values,
        'last_price': _quantize_to_tick(ltp, _get_instrument_tick(symbol, exchange)),
    }

    if dry_run:
        trigger_id = 'DRY-GTT-' + str(uuid.uuid4())[:6]
        return jsonify({
            'success': True, 'triggerId': trigger_id, 'dry_run': True,
            'sent': {'type': gtt_type, 'condition': condition, 'orders': orders},
        })

    access_token = zerodha_sessions[api_key].get('access_token', '')
    payload = _up.urlencode({
        'type':      gtt_type,
        'condition': _json.dumps(condition),
        'orders':    _json.dumps(orders),
    }).encode('utf-8')
    req = _zd_urllib.Request(
        'https://api.kite.trade/gtt/triggers',
        data=payload,
        headers={
            'X-Kite-Version': '3',
            'Authorization':  'token {}:{}'.format(api_key, access_token),
            'Content-Type':   'application/x-www-form-urlencoded',
            'User-Agent':     'Mozilla/5.0',
        }, method='POST'
    )
    try:
        with _kite_urlopen(req, timeout=15) as resp:
            body = resp.read().decode('utf-8')
        resp_data = _json.loads(body) if body else {}
    except _ue.HTTPError as e:
        err_body = ''
        try:
            err_body = e.read().decode('utf-8')
        except Exception:
            pass
        try:
            err_data = _json.loads(err_body)
            err_msg = err_data.get('message', err_body[:300])
        except Exception:
            err_msg = err_body[:300] or str(e)
        return jsonify({
            'success': False,
            'error': 'Kite GTT HTTP {}: {} (sent: {} {} qty={} type={} SL={} T={})'.format(
                e.code, err_msg, side, symbol, qty, gtt_type, sl_price, target_price
            ),
            'sent': {'type': gtt_type, 'condition': condition, 'orders': orders},
        })
    except Exception as e:
        return jsonify({'success': False, 'error': 'Kite GTT request failed: {}'.format(e)})

    if resp_data.get('status') == 'success':
        trigger_id = resp_data.get('data', {}).get('trigger_id', '')
        return jsonify({'success': True, 'triggerId': trigger_id})
    return jsonify({'success': False, 'error': resp_data.get('message', 'GTT rejected'), 'data': resp_data})

# ============================================================================
# Delta Exchange Integration (crypto derivatives — INR settlement on some pairs)
# Public docs: https://docs.delta.exchange/
# Base URL: https://api.delta.exchange
# Auth: HMAC-SHA256 signature header on private endpoints.
#   Signature payload = method + timestamp + request_path + query_string + body
# ============================================================================
delta_v2_sessions = {}  # api_key -> {api_secret, base_url, connected}

_DELTA_PRODUCT_CACHE = {'ts': 0.0, 'by_symbol': {}, 'base_url': ''}
_DELTA_PRODUCT_TTL   = 3600

# Delta runs two regional clusters. Indian users register at delta.exchange
# but their keys live on the India host — calls to the global host return
# auth failures even when keys are valid. Try India first, fall back to global.
_DELTA_BASES = ['https://api.india.delta.exchange', 'https://api.delta.exchange']

def _delta_sign(api_secret, method, path, query_string='', body=''):
    """HMAC-SHA256 signature for a Delta Exchange API call.
    Returns (signature_hex, timestamp_str)."""
    import hmac, hashlib
    ts = str(int(_zd_time.time()))
    payload = method.upper() + ts + path + (query_string or '') + (body or '')
    sig = hmac.new(api_secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return sig, ts

def _delta_request(api_key, api_secret, method, path, params=None, body=None, timeout=15, base_url=None):
    """Make a signed HTTPS request to Delta Exchange. Returns parsed JSON dict;
    on transport/parse failure returns {success: False, error: ...}.

    When base_url is None we don't fall back — call _delta_connect_try_bases
    for that. For requests after the session is established, the bound
    session base_url is passed in explicitly."""
    import urllib.request as _ur, urllib.parse as _up, urllib.error as _ue, json as _json
    base = base_url or _DELTA_BASES[0]
    query_string = ''
    if params:
        query_string = '?' + _up.urlencode(params, doseq=True)
    body_str = ''
    if body is not None and method.upper() != 'GET':
        body_str = body if isinstance(body, str) else _json.dumps(body, separators=(',', ':'))
    sig, ts = _delta_sign(api_secret, method, path, query_string, body_str)
    url = base + path + query_string
    headers = {
        'api-key':      api_key,
        'signature':    sig,
        'timestamp':    ts,
        'Content-Type': 'application/json',
        'Accept':       'application/json',
        'User-Agent':   'mangal-view/1.0',
    }
    data = body_str.encode('utf-8') if body_str else None
    req = _ur.Request(url, data=data, headers=headers, method=method.upper())
    try:
        with _ur.urlopen(req, timeout=timeout) as resp:
            txt = resp.read().decode('utf-8')
        return _json.loads(txt) if txt else {'success': False, 'error': 'empty response'}
    except _ue.HTTPError as e:
        err_body = ''
        try:
            err_body = e.read().decode('utf-8')
        except Exception:
            pass
        # Try to parse Delta's structured error
        msg = err_body[:500] or str(e)
        code = None
        try:
            err_data = _json.loads(err_body)
            err_obj  = err_data.get('error') if isinstance(err_data.get('error'), dict) else None
            code     = (err_obj or {}).get('code')
            msg      = (err_obj or {}).get('code') or err_data.get('message') or err_body[:500]
        except Exception:
            pass
        return {'success': False, 'error': 'Delta HTTP {}: {} (host={})'.format(e.code, msg, base),
                'http_code': e.code, 'delta_code': code, 'host': base, 'raw': err_body[:500]}
    except Exception as e:
        return {'success': False, 'error': 'Delta request failed: {} (host={})'.format(e, base), 'host': base}

def _delta_get_public(path, params=None, base_url=None, timeout=20):
    """GET a public Delta endpoint (no auth). When base_url is None, try the
    India host first then global, returning the first that succeeds. Returns
    {success, result?, error?, host}."""
    import urllib.request as _ur, urllib.parse as _up, urllib.error as _ue, json as _json
    qs = ('?' + _up.urlencode(params, doseq=True)) if params else ''
    bases = [base_url] if base_url else list(_DELTA_BASES)
    last = None
    for base in bases:
        url = base + path + qs
        try:
            req = _ur.Request(url, headers={'User-Agent': 'mangal-view/1.0'})
            with _ur.urlopen(req, timeout=timeout) as resp:
                data = _json.loads(resp.read().decode('utf-8'))
            data['host'] = base
            return data
        except _ue.HTTPError as e:
            try:    err = e.read().decode('utf-8')[:300]
            except Exception: err = str(e)
            last = {'success': False, 'error': 'HTTP {}: {}'.format(e.code, err), 'host': base, 'http_code': e.code}
        except Exception as e:
            last = {'success': False, 'error': str(e), 'host': base}
    return last or {'success': False, 'error': 'no hosts tried'}

def _load_delta_products():
    """Cache Delta's /v2/products list. Tries India host first, then global —
    the two regions serve different product catalogs (India has USDT
    perpetuals like BTCUSDT, global has USD perpetuals like BTCUSD)."""
    now = _zd_time.time()
    if now - _DELTA_PRODUCT_CACHE['ts'] < _DELTA_PRODUCT_TTL and _DELTA_PRODUCT_CACHE['by_symbol']:
        return _DELTA_PRODUCT_CACHE['by_symbol']
    resp = _delta_get_public('/v2/products')
    if not resp.get('success'):
        return _DELTA_PRODUCT_CACHE.get('by_symbol', {})
    by_symbol = {}
    for p in (resp.get('result') or []):
        sym = (p.get('symbol') or '').upper()
        if not sym:
            continue
        # Pull contract specs needed for accurate P/L math. Delta contracts
        # don't represent 1 whole unit of the underlying — e.g., 1 BTCUSD
        # perpetual contract on Delta India = 0.001 BTC worth. Without the
        # multiplier, the bot reports point-deltas as P/L, which can be 1000x
        # off from what Delta actually settles to your wallet.
        try:    _cv = float(p.get('contract_value', 0) or 0)
        except (TypeError, ValueError): _cv = 0.0
        if _cv <= 0:
            try:    _cv = float(p.get('lot_size', 0) or 0)
            except (TypeError, ValueError): _cv = 0.0
        if _cv <= 0: _cv = 1.0
        by_symbol[sym] = {
            'id':             p.get('id'),
            'symbol':         p.get('symbol'),
            'description':    p.get('description', ''),
            'contract_type':  p.get('contract_type', ''),
            'tick_size':      float(p.get('tick_size', 0) or 0),
            'state':          p.get('state', ''),
            'strike_price':   p.get('strike_price'),                 # options: strike (str/num) or None
            'settlement_time': p.get('settlement_time', ''),         # options: ISO expiry
            # New: contract specs for accurate P/L
            'contract_value': _cv,                                # multiplier per contract (e.g. 0.001 for BTCUSD)
            'notional_type':  (p.get('notional_type') or 'vanilla'),  # vanilla | inverse | quanto
            'underlying':     p.get('underlying_asset', {}).get('symbol', '') if isinstance(p.get('underlying_asset'), dict) else '',
            'settling':       p.get('settling_asset', {}).get('symbol', '') if isinstance(p.get('settling_asset'), dict) else '',
        }
    _DELTA_PRODUCT_CACHE['ts']        = now
    _DELTA_PRODUCT_CACHE['by_symbol'] = by_symbol
    _DELTA_PRODUCT_CACHE['base_url']  = resp.get('host', '')
    return by_symbol

_LAST_DELTA_ERROR = {'msg': '', 'host': '', 'symbol': ''}

def fetch_delta_data(interval_key, symbol):
    """Fetch OHLCV candles from Delta's public history endpoint. No auth.
    Tries India host first then global. Records the last error in
    _LAST_DELTA_ERROR so /api/candles can surface it to the user."""
    if not symbol:
        return []
    interval_map = {
        '1m': '1m', '3m': '3m', '5m': '5m', '10m': '5m',
        '15m': '15m', '30m': '30m',
        '1h': '1h', '2h': '1h', '4h': '4h', '1d': '1d'
    }
    res = interval_map.get(interval_key, '5m')
    from datetime import timezone as _tz
    now = int(datetime.now(_tz.utc).timestamp())
    if res in ('1d',):     days = 200
    elif res in ('1h','2h','4h'):  days = 30
    else:                  days = 5
    start = now - days * 86400
    params = {'symbol': symbol, 'resolution': res, 'start': start, 'end': now}
    # Prefer whichever host the products cache used (if any) — same region.
    preferred = _DELTA_PRODUCT_CACHE.get('base_url') or None
    bases = [preferred] if preferred else list(_DELTA_BASES)
    last_err = None
    rows = None
    used_host = None
    for base in bases:
        resp = _delta_get_public('/v2/history/candles', params=params, base_url=base)
        if resp.get('success'):
            rows = resp.get('result') or []
            used_host = base
            break
        last_err = resp.get('error') or 'unknown'
    if rows is None:
        # If we tried the preferred host first and it failed, also try the other one.
        if preferred:
            for base in _DELTA_BASES:
                if base == preferred: continue
                resp = _delta_get_public('/v2/history/candles', params=params, base_url=base)
                if resp.get('success'):
                    rows = resp.get('result') or []; used_host = base
                    break
                last_err = resp.get('error') or last_err
    if rows is None or not rows:
        _LAST_DELTA_ERROR.update({'msg': last_err or 'no candles', 'host': used_host or '', 'symbol': symbol})
        return []
    candles = []
    for c in rows:
        try:
            candles.append({
                'time':   int(c.get('time', 0)),
                'open':   float(c.get('open', 0)),
                'high':   float(c.get('high', 0)),
                'low':    float(c.get('low', 0)),
                'close':  float(c.get('close', 0)),
                'volume': float(c.get('volume', 0) or 0),
            })
        except Exception:
            continue
    # Delta returns candles in DESCENDING time order. LightweightCharts
    # silently rejects setData() when the time series isn't ascending —
    # so sort ascending and dedupe by timestamp before returning.
    if candles:
        candles.sort(key=lambda x: x['time'])
        deduped = []
        prev_t = None
        for c in candles:
            if c['time'] != prev_t:
                deduped.append(c)
                prev_t = c['time']
        candles = deduped
        # Delta returns raw UTC unix seconds. LightweightCharts displays the
        # time axis as UTC by default, so without a shift the chart would
        # read 5h30m behind IST. Match the rest of this app's convention
        # (fetch_nifty_data also adds IST_OFFSET) — gives correct IST display.
        for c in candles:
            c['time'] = c['time'] + IST_OFFSET
    if interval_key in ('2h', '4h') and candles:
        n = 2 if interval_key == '2h' else 4
        agg = []
        for i in range(0, len(candles), n):
            grp = candles[i:i + n]
            if not grp: continue
            agg.append({
                'time':   grp[0]['time'],
                'open':   grp[0]['open'],
                'high':   max(c['high'] for c in grp),
                'low':    min(c['low']  for c in grp),
                'close':  grp[-1]['close'],
                'volume': sum(c['volume'] for c in grp),
            })
        candles = agg
    _LAST_DELTA_ERROR.update({'msg': '', 'host': used_host or '', 'symbol': symbol})
    return candles

@app.route('/api/delta/connect', methods=['POST'])
@login_required
def delta_connect():
    """Validate Delta credentials by calling /v2/wallet/balances.
    Tries the India host first (most users), falls back to the global host.
    Returns clear diagnostic info on failure so the user can debug."""
    data = request.json or {}
    api_key    = (data.get('api_key') or '').strip()
    api_secret = (data.get('api_secret') or '').strip()
    forced_base = (data.get('base_url') or '').strip().rstrip('/')
    if not api_key or not api_secret:
        return jsonify({'success': False, 'error': 'API Key and API Secret are required.'}), 400

    attempts = []
    bases    = [forced_base] if forced_base else list(_DELTA_BASES)
    for base in bases:
        result = _delta_request(api_key, api_secret, 'GET', '/v2/wallet/balances', base_url=base)
        attempts.append({'host': base, 'ok': bool(result.get('success')),
                         'http_code': result.get('http_code'),
                         'delta_code': result.get('delta_code'),
                         'error': None if result.get('success') else result.get('error')})
        if result.get('success'):
            delta_v2_sessions[api_key] = {'api_secret': api_secret, 'base_url': base, 'connected': True}
            return jsonify({'success': True, 'message': 'Connected', 'host': base,
                            'attempts': attempts})

    # All hosts failed — return rich diagnostics
    last = attempts[-1] if attempts else {}
    hint = _delta_diag_hint(last)
    return jsonify({
        'success': False,
        'error':   'Could not authenticate against any Delta host. ' + hint,
        'attempts': attempts,
        'hosts_tried': bases,
    })

def _delta_diag_hint(last_attempt):
    """Map common Delta error codes / HTTP codes to a one-line hint."""
    code  = (last_attempt.get('delta_code') or '').lower() if isinstance(last_attempt.get('delta_code'), str) else ''
    http  = last_attempt.get('http_code') or 0
    err   = (last_attempt.get('error') or '').lower()
    if 'invalid_api_key' in code or 'unauthorized' in code or http == 401:
        return ('Likely cause: API key not recognised on this host. '
                'If you registered at delta.exchange (India), the key only works on the India host '
                'and vice versa. Also confirm the key exists and is enabled at '
                'https://www.delta.exchange/app/account/manage-api-keys')
    if 'signature_mismatch' in code or 'invalid_signature' in code:
        return ('Signature mismatch — the API Secret might be wrong (re-copy without trailing spaces), '
                'or the server clock is skewed (Delta requires within ~5s).')
    if 'ip_not_whitelisted' in code:
        return ('Your outbound IP is not on the API key\'s allowlist. '
                'Open the key on Delta and either remove IP restriction or add this server\'s IP. '
                'Use /api/myip while logged in to see the IP this server uses.')
    if 'inactive' in code or 'disabled' in code:
        return ('API key is inactive — enable it on the Delta API keys page.')
    if http == 404:
        return ('404 on /v2/wallet/balances — possible regional API mismatch. '
                'Try delta.exchange (global) explicitly if you registered there.')
    if 'expired' in code or 'timestamp' in code:
        return ('Timestamp rejection — server clock is more than ~5s off Delta\'s. '
                'Sync system clock (Windows: time settings → Sync now).')
    return ('Open DevTools console and the /api/delta/connect response for the exact Delta error code. '
            'Common fixes: try the other regional host (delta.exchange ↔ india.delta.exchange), '
            're-copy keys, enable Trading permission, wait 10 min if the key is brand new.')

@app.route('/api/delta/verify', methods=['GET'])
@login_required
def delta_verify():
    """Real connection check — confirms the stored Delta key still authenticates
    via /v2/wallet/balances. Returns {connected: bool}."""
    api_key = request.args.get('api_key', '').strip()
    if not api_key or api_key not in delta_v2_sessions:
        return jsonify({'connected': False, 'error': 'no server session'})
    sess = delta_v2_sessions[api_key]
    res = _delta_request(api_key, sess['api_secret'], 'GET', '/v2/wallet/balances', base_url=sess.get('base_url'))
    return jsonify({'connected': bool(res.get('success')), 'error': res.get('error', '')})

@app.route('/api/delta/products')
@login_required
def delta_products():
    """Search Delta products by symbol substring."""
    q = (request.args.get('q') or '').strip().upper()
    products = _load_delta_products()
    if not products:
        return jsonify({'success': False, 'error': 'Could not fetch Delta products', 'results': []})
    out = []
    for sym, p in products.items():
        if not q or q in sym or q in (p.get('description', '') or '').upper():
            out.append(p)
            if len(out) >= 200:
                break
    return jsonify({'success': True, 'results': out, 'total': len(products)})

@app.route('/api/delta/order', methods=['POST'])
@login_required
def delta_place_order():
    """Place a Delta Exchange order. Honors dry_run (default true)."""
    data = request.json or {}
    api_key    = (data.get('api_key') or '').strip()
    symbol     = (data.get('symbol') or '').strip().upper()
    side       = (data.get('side') or '').upper()        # BUY / SELL -> buy / sell
    qty        = int(data.get('qty', 1) or 1)
    order_type = (data.get('order_type') or 'market_order').strip()
    price      = data.get('price')
    dry_run    = data.get('dry_run', True)
    algo       = data.get('algo', '')

    if api_key not in delta_v2_sessions:
        return jsonify({'success': False, 'error': 'Not connected (open Delta Login)'}), 403
    if side not in ('BUY', 'SELL'):
        return jsonify({'success': False, 'error': 'Invalid side'}), 400
    if not symbol:
        return jsonify({'success': False, 'error': 'Missing symbol'}), 400

    if dry_run:
        order_id = 'DRY-D-' + str(uuid.uuid4())[:6]
        return jsonify({'success': True, 'orderId': order_id, 'dry_run': True,
                        'sent': {'symbol': symbol, 'side': side, 'qty': qty, 'order_type': order_type}})

    api_secret = delta_v2_sessions[api_key]['api_secret']
    products   = _load_delta_products()
    p          = products.get(symbol)
    if not p or not p.get('id'):
        return jsonify({'success': False, 'error': 'Unknown Delta symbol: ' + symbol})
    body = {
        'product_id': p['id'],
        'size':       qty,
        'side':       'buy' if side == 'BUY' else 'sell',
        'order_type': order_type,   # 'market_order' or 'limit_order'
    }
    if order_type == 'limit_order' and price is not None:
        body['limit_price'] = str(price)
    sess_base = delta_v2_sessions[api_key].get('base_url') or _DELTA_BASES[0]
    result = _delta_request(api_key, api_secret, 'POST', '/v2/orders', body=body, base_url=sess_base)
    if result.get('success'):
        oid = (result.get('result') or {}).get('id', '')
        entry = {'order_id': oid, 'symbol': symbol, 'side': side, 'qty': qty,
                 'order_type': order_type, 'price': price, 'algo': algo,
                 'status': 'PLACED', 'timestamp': datetime.utcnow().isoformat()}
        return jsonify({'success': True, 'orderId': oid, 'order': entry})
    return jsonify({'success': False,
                    'error': result.get('error', 'Delta order rejected'),
                    'sent': body})

@app.route('/api/delta/positions')
@login_required
def delta_positions():
    """Return current positions as {symbol: net_size}. Used by the bot to detect
    external exits and reset local state."""
    api_key = (request.args.get('api_key') or '').strip()
    if api_key not in delta_v2_sessions:
        return jsonify({'success': False, 'error': 'Not connected', 'positions': {}})
    api_secret = delta_v2_sessions[api_key]['api_secret']
    sess_base  = delta_v2_sessions[api_key].get('base_url') or _DELTA_BASES[0]
    result = _delta_request(api_key, api_secret, 'GET', '/v2/positions/margined', base_url=sess_base)
    if not result.get('success'):
        # Try the alternative endpoint name
        result = _delta_request(api_key, api_secret, 'GET', '/v2/positions', base_url=sess_base)
    positions = {}
    for p in (result.get('result') or []):
        sym  = (p.get('product', {}) or {}).get('symbol') or p.get('symbol', '')
        size = p.get('size', 0)
        if sym:
            try: positions[sym.upper()] = int(size or 0)
            except (TypeError, ValueError): positions[sym.upper()] = 0
    return jsonify({'success': True, 'positions': positions})

# ============================================================================
# Server-side Delta AI Bot (Option C — autonomous bot that runs on the server,
# survives browser tab close, only needs the tab open for monitoring).
# ============================================================================
import threading as _threading

# Single in-memory bot instance. (Multi-user scaling would key by user_id.)
delta_ai_state = {
    'running':       False,
    'paused':        False,
    'thread':        None,
    'config':        None,   # {symbol, qty, tf, mode, slPct, tpPct, maxConsec, maxLoss, minScore, includeMM, includeMMA, api_key}
    'position':      None,   # {side, entryPrice, entryTime, qty, sl, tp, strategy, mode}
    'trades':        [],     # closed trades
    'consec_losses': 0,
    'last_tick':     {},     # {time, price, strategy, regime, signal, score, error?}
    'log_buffer':    [],     # last ~500 UI log lines for browser display
    'last_candles':  [],     # last ~150 candles for browser chart
}
delta_ai_lock = _threading.RLock()

# Server-side Zerodha (Kite) AI bot — mirrors delta_ai_state. Runs on the server
# so it keeps trading even when the browser tab is closed.
zd_ai_state = {
    'running':       False,
    'paused':        False,
    'thread':        None,
    'config':        None,   # {symbol, exchange, qty, tf, mode, slPct, tpPct, maxConsec, maxLoss, maxProfit, minScore, cooldownSec, qualityFilter, includeMM, includeMMA, api_key}
    'position':      None,
    'trades':        [],
    'consec_losses': 0,
    'last_exit_time': 0,
    'last_tick':     {},
    'log_buffer':    [],
    'last_candles':  [],
}
zd_ai_lock = _threading.RLock()

def _zd_log(msg):
    """Append a UI-only log line to the Zerodha bot's circular buffer."""
    ts = _bot_log_ts()
    with zd_ai_lock:
        buf = zd_ai_state.setdefault('log_buffer', [])
        buf.append('[' + ts + '] ' + msg)
        if len(buf) > 200:           # circular buffer: keep newest 200, drop oldest
            del buf[:len(buf) - 200]

def _bot_log(msg):
    """Append a UI-only log line to the bot's circular buffer."""
    ts = datetime.now(_tz_module.timezone(_tz_module.timedelta(seconds=IST_OFFSET))).strftime('%H:%M:%S') \
         if False else _bot_log_ts()
    with delta_ai_lock:
        buf = delta_ai_state.setdefault('log_buffer', [])
        buf.append('[' + ts + '] ' + msg)
        if len(buf) > 200:           # circular buffer: keep newest 200, drop oldest
            del buf[:len(buf) - 200]

def _bot_log_ts():
    from datetime import timezone, timedelta
    return datetime.now(timezone(timedelta(seconds=IST_OFFSET))).strftime('%H:%M:%S')

def _persist_log_line(line):
    """Append a trade-meaningful line to log.txt. Mirrors what the browser
    persistLog() endpoint did, but called directly from the server.
    Timestamps are IST (UTC+5:30) so the log matches the user's clock."""
    from datetime import datetime as _dt, timezone as _tzc, timedelta as _tdc
    ts = _dt.now(_tzc(_tdc(seconds=IST_OFFSET))).isoformat()
    path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'log.txt')
    try:
        with open(path, 'a', encoding='utf-8') as f:
            f.write('[' + ts + '] ' + line + '\n')
    except Exception:
        pass
    try:
        _tg_enqueue('[' + ts + '] ' + line)   # forward to Telegram if events-forwarding is on
    except Exception:
        pass

# --- Build a signal-summary dict for the bot, mirroring api_candles --
# Doesn't need request context. Reuses every compute_*/generate_*_signals
# helper already defined in this file.
def _bot_signal_data(symbol, interval, source, algo_names, api_key=None):
    if source == 'delta':
        candles = fetch_delta_data(interval, symbol)
    elif source == 'kite':
        candles = fetch_kite_data(interval, symbol, api_key=api_key)
    elif source == 'mt5':
        candles = fetch_mt5_data(interval, symbol, api_key)   # api_key carries the MT5 session id
    elif source == 'tradingview':
        candles = fetch_tradingview_data(interval, symbol)
    elif source == 'nse':
        candles = fetch_nse_data(interval, symbol)
    else:
        candles = fetch_nifty_data(interval, symbol)
    if not candles or len(candles) < 20:
        return {'candles': candles or [], 'signalSummary': {}, 'lastPrice': (candles[-1]['close'] if candles else 0)}

    supertrend = compute_supertrend(candles, 10, 3.0)
    psar       = compute_parabolic_sar(candles, 0.02, 0.02, 0.2)
    sr         = compute_support_resistance(candles)
    rsi_data   = compute_rsi(candles)
    macd_data  = compute_macd(candles)
    vwap_data  = compute_vwap(candles)
    ema9       = compute_ema_series(candles, 9)
    ema21      = compute_ema_series(candles, 21)
    patterns   = detect_candlestick_patterns(candles)
    bb         = compute_bollinger_bands(candles, 20, 2.0)

    summaries = {}
    for algo in algo_names:
        try:
            if algo == 'trend':
                _sigs, summ = generate_signals(candles, supertrend, psar, rsi_data, macd_data, vwap_data, ema9, ema21, patterns, sr)
            elif algo == 'mstreet':
                _sigs, summ = generate_janestreet_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'mfactor':
                _sigs, summ = generate_accurate_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'sniper':
                _sigs, summ = generate_sniper_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'orderflow':
                _sigs, summ = generate_orderflow_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'priceaction':
                _sigs, summ = generate_priceaction_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'breakout':
                _sigs, summ = generate_breakout_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'momentum':
                _sigs, summ = generate_momentum_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'scalping':
                _sigs, summ = generate_scalping_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'smartmoney':
                _sigs, summ = generate_smartmoney_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'quant':
                _sigs, summ = generate_quant_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'hybrid':
                _sigs, summ = generate_hybrid_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'statarb':
                _sigs, summ = generate_statarb_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'institution':
                _sigs, summ = generate_institution_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'marketmaking':
                _sigs, summ = generate_marketmaking_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            elif algo == 'mma':
                _sigs, summ = generate_mma_signals(candles, bb, rsi_data, macd_data, vwap_data, ema9, ema21, sr)
            else:
                continue
            summaries[algo] = summ
        except Exception:
            continue

    return {'candles': candles, 'signalSummary': summaries, 'lastPrice': candles[-1]['close']}

# --- Regime detector + strategy selector (Python port of JS bot logic) ---
def _bot_detect_regime(candles):
    n = min(20, len(candles))
    if n < 5:
        return {'volatility': 'low', 'trending': False, 'direction': 'flat', 'volPct': 0.0, 'trendPct': 0.0}
    w = candles[-n:]
    ranges = [c['high'] - c['low'] for c in w]
    avg_range = sum(ranges) / n
    avg_price = sum(c['close'] for c in w) / n
    vol_pct   = (avg_range / avg_price * 100.0) if avg_price else 0.0
    trend_pct = ((w[-1]['close'] - w[0]['close']) / w[0]['close'] * 100.0) if w[0]['close'] else 0.0
    return {
        'volatility': 'high' if vol_pct > 1.5 else 'low',
        'trending':   abs(trend_pct) > 1.0,
        'direction':  'up' if trend_pct > 0 else ('down' if trend_pct < 0 else 'flat'),
        'volPct':     vol_pct, 'trendPct': trend_pct,
    }

def _bot_select_strategy(regime, summaries, cfg):
    # Candidates = every strategy that was COMPUTED this tick, which is exactly
    # the always-on core plus the user-selected configurable strategies (see the
    # algos list built in each *_bot_tick). We pick the strongest |score| among
    # them; regime safety is enforced separately by _bot_entry_quality. This is
    # what makes the strategy checkboxes authoritative — an unticked strategy is
    # never computed, so it can never become the active strategy.
    best = None
    for name, sm in summaries.items():
        if not sm: continue
        score = sm.get('score') if sm.get('score') is not None else sm.get('composite_score')
        if score is None: continue
        try: score = float(score)
        except (TypeError, ValueError): continue
        if best is None or abs(score) > abs(best['score']):
            best = {'name': name, 'score': score}
    if not best:
        return {'name': 'wait', 'signal': 'HOLD', 'score': 0.0,
                'reason': '{} vol, {} • no algo data'.format(
                    regime['volatility'], 'trending' if regime['trending'] else 'range')}

    user_min  = float(cfg.get('minScore', 4.0))
    # Score buffer (panel setting): extra edge required above Min score before
    # entering. Full buffer in calm markets (more chop / less follow-through),
    # half in volatile ones. buffer=0 makes Min score the literal threshold.
    buf       = float(cfg.get('scoreBuffer', 1.0))
    threshold = user_min + (buf * 0.5 if regime['volatility'] == 'high' else buf)
    signal = 'HOLD'
    if best['score'] >=  threshold: signal = 'BUY'
    if best['score'] <= -threshold: signal = 'SELL'
    return {'name': best['name'], 'signal': signal, 'score': best['score'],
            'reason': '{} vol {:.2f}% • {} • score {:.1f} vs ±{:.1f}'.format(
                regime['volatility'], regime['volPct'],
                'trending ' + regime['direction'] + ' ' + '{:.2f}'.format(regime['trendPct']) + '%' if regime['trending'] else 'range',
                best['score'], threshold)}

def _bot_entry_quality(side, candles, regime, cfg):
    """High-win-rate gate applied just before an entry. Blocks the two losing
    patterns seen in log.txt: (1) counter-trend knife-catching, and (2) chasing
    a move that is already over-extended from its mean (buying the top). Returns
    (ok: bool, reason: str)."""
    if cfg.get('qualityFilter') is False:
        return True, ''
    n = min(20, len(candles))
    if n < 10:
        return True, ''   # not enough data to judge — don't block
    w      = candles[-n:]
    closes = [c['close'] for c in w]
    sma    = sum(closes) / n
    avg_rng = sum(c['high'] - c['low'] for c in w) / n
    price   = candles[-1]['close']

    # (1) Trend alignment: never fade a clearly trending market.
    if regime['trending']:
        if side == 'BUY' and regime['direction'] == 'down':
            return False, 'against downtrend'
        if side == 'SELL' and regime['direction'] == 'up':
            return False, 'against uptrend'

    # (2) Extension guard: skip entries that are chasing a stretched move.
    if avg_rng > 0:
        ext = (price - sma) / avg_rng
        if side == 'BUY' and ext > 1.5:
            return False, 'overextended above mean ({:.1f}x range)'.format(ext)
        if side == 'SELL' and ext < -1.5:
            return False, 'overextended below mean ({:.1f}x range)'.format(-ext)
    return True, ''

def _bot_efficiency_ratio(candles, cfg=None):
    """Kaufman efficiency ratio: ER = |net move| / |path travelled| over the lookback
    (rangeLook, default 20). ER→1 = clean trend, ER→0 = back-and-forth chop. Returns
    a float in [0,1], or None when there isn't enough data. Instrument-agnostic."""
    n = min(int((cfg or {}).get('rangeLook', 20) or 20), len(candles))
    if n < 10:
        return None
    closes = [c['close'] for c in candles[-n:]]
    net  = abs(closes[-1] - closes[0])
    path = sum(abs(closes[i] - closes[i - 1]) for i in range(1, len(closes)))
    if path <= 0:
        return 0.0
    return net / path

def _bot_is_ranging(candles, cfg):
    """Chop filter: True when the efficiency ratio is below minER (default 0.28).
    Used to SKIP TV entries/continuation in ranges (the GOLDTEN/SOL losing clusters
    all had ER near 0). Turn off with avoidRange=False."""
    if not cfg.get('avoidRange', True):
        return False
    er = _bot_efficiency_ratio(candles, cfg)
    if er is None:
        return False                      # not enough data — don't block
    return er < float(cfg.get('minER', 0.28) or 0.28)

def _bot_er_tag(candles, cfg):
    """Short market-state tag for tick logs/display, e.g. 'ER 0.42 trend' / 'ER 0.11 chop'."""
    er = _bot_efficiency_ratio(candles, cfg)
    if er is None:
        return 'ER —'
    return 'ER {:.2f} {}'.format(er, 'chop' if er < float((cfg or {}).get('minER', 0.28) or 0.28) else 'trend')

def _bot_defer_entry(state, cfg, strat):
    """Remember a chop-skipped entry so it can be taken once ER recovers (within a
    freshness window pendingSec, default 600s). Stores the side + the alert's SL/TP."""
    _sec = cfg.get('pendingSec', 60)
    _sec = int(_sec) if _sec is not None else 60
    if _sec <= 0:
        return   # deferral disabled (Defer ER = 0)
    state['_pending'] = {
        'side': strat['signal'], 'slPct': strat.get('slPct'), 'tpPct': strat.get('tpPct'),
        'expires': int(_zd_time.time()) + _sec,
    }

def _bot_take_deferred(state, cfg, candles, price, open_fn, mode):
    """If a chop-skipped entry is pending and ER has now RECOVERED (and it's still
    fresh), open it. Returns True if it opened. Implements 'deferred entry on ER
    recovery'; the position then rides the normal TP-continuation logic."""
    pend = state.get('_pending')
    if not pend:
        return False
    if int(_zd_time.time()) > int(pend.get('expires', 0)):
        state.pop('_pending', None); return False   # expired before ER recovered
    if _bot_is_ranging(candles, cfg):
        return False                                  # still choppy — keep waiting
    side = pend.get('side')
    state.pop('_pending', None)
    strat = {'name': 'tv', 'signal': side, 'score': 10.0, 'seed': True,
             'reason': 'deferred entry (ER recovered)',
             'slPct': pend.get('slPct'), 'tpPct': pend.get('tpPct')}
    open_fn(side, price, strat, mode)
    if state.get('position'):
        state['position']['entryBarTime'] = candles[-1].get('time')
    return True

# Always-on reliable strategies (the "core") + the user-configurable opt-ins
# exposed as checkboxes in both AI bot panels.
_BOT_CORE_ALGOS         = ['trend', 'momentum', 'breakout', 'smartmoney', 'orderflow']
_BOT_CONFIGURABLE_ALGOS = ['mfactor', 'mstreet', 'sniper', 'scalping', 'quant', 'hybrid', 'mpredict', 'institution', 'statarb', 'priceaction', 'claude']
# Default opt-ins when a client doesn't send allowedStrategies (preserves the
# pre-checkbox behaviour: the old always-on set minus sniper, which caused the
# biggest losses, and mpredict, which is only a chart overlay).
_BOT_DEFAULT_ALLOWED    = ['mfactor', 'mstreet', 'scalping', 'quant', 'hybrid', 'institution', 'statarb']

def _bot_is_claude(cfg):
    """True when the 'Claude AI' strategy is selected — Claude decides trades on
    its own and NONE of the core/algo strategies are used."""
    return 'claude' in (cfg.get('allowedStrategies') or [])

def _bot_cfg_summary(cfg, extra=None):
    """One-line dump of every configurable parameter, logged to log.txt on Start so a
    session can be reproduced/audited from the log alone."""
    keys = ['mode', 'symbol', 'symbols', 'autoSymbol', 'exchange', 'qty', 'tf',
            'capital', 'leverage', 'slPct', 'tpPct', 'maxConsec', 'maxLoss', 'maxProfit',
            'minScore', 'scoreBuffer', 'cooldownSec', 'tickSec', 'qualityFilter',
            'avoidRange', 'minER', 'rangeLook', 'maxCont', 'contSlPct', 'trendGate',
            'emaMode', 'pendingSec', 'maxSeedSlPct', 'hardStop', 'tvEnabled', 'tvSymbol', 'model']
    parts = ['claude=' + str(_bot_is_claude(cfg))]
    for k in keys:
        if k in cfg and cfg.get(k) not in (None, '', []):   # keep 0 / False (meaningful)
            parts.append('{}={}'.format(k, cfg.get(k)))
    if cfg.get('allowedStrategies'):
        parts.append('strategies=' + ','.join(cfg.get('allowedStrategies')))
    for k, v in (extra or {}).items():
        parts.append('{}={}'.format(k, v))
    return ' '.join(parts)

def _bot_fetch_candles(symbol, interval, source, api_key=None):
    """Lightweight candle fetch for the bots. Claude-only mode needs raw candles,
    NOT the 14-indicator bundle _bot_signal_data builds every tick — skipping it
    cuts per-tick memory churn massively (was OOMing Render after a couple hours)."""
    try:
        if source == 'kite':  return fetch_kite_data(interval, symbol, api_key=api_key) or []
        if source == 'mt5':   return fetch_mt5_data(interval, symbol, api_key) or []
        return fetch_delta_data(interval, symbol) or []
    except Exception:
        return []

# Seconds between bot ticks. In Claude-AI mode each tick = one Anthropic API
# call per running bot/leg, so this directly drives API credit usage:
# 15s=240 calls/hr, 30s=120, 60s=60. Override via BOT_TICK_SEC (min 5).
_BOT_TICK_SEC = max(5, int(os.environ.get('BOT_TICK_SEC', '30') or 30))

import gc as _gc
def _bot_gc_tick(_c=[0]):
    """Throttled gc.collect() called from each bot loop — returns freed memory to
    the heap so long-running bots don't slowly climb toward Render's 512MB cap."""
    _c[0] += 1
    if _c[0] % 16 == 0:
        try: _gc.collect()
        except Exception: pass

def _bot_build_algos(cfg):
    """Candidate algo pool = always-on core + user-selected configurable
    strategies (+ MM/MMA opt-ins). 'mpredict' is dropped — it has no trading
    signal (chart prediction overlay only). When Claude AI mode is on, NO algos
    are computed (Claude trades independently)."""
    if _bot_is_claude(cfg):
        return []
    algos = list(_BOT_CORE_ALGOS)
    allowed = cfg.get('allowedStrategies')
    if allowed is None:
        allowed = _BOT_DEFAULT_ALLOWED
    for s in allowed:
        if s in _BOT_CONFIGURABLE_ALGOS and s not in algos:
            algos.append(s)
    if cfg.get('includeMM'):  algos.append('marketmaking')
    if cfg.get('includeMMA'): algos.append('mma')
    return [a for a in algos if a not in ('mpredict', 'claude')]

# ============================================================================
# TradingView integration. There is NO official API for a user's private chart
# indicators, so this provides the realistic equivalents the bots feed to Claude
# (context only) when the panel's TradingView toggle is on:
#   (1) Technical Analysis readout via TradingView's public scanner endpoint
#       (RSI/MACD/Stoch/ADX + an overall STRONG BUY..STRONG SELL rating), and
#   (2) custom-indicator signals the user PUSHES in via TradingView alert webhooks.
# ============================================================================
_TV_TA_CACHE = {}        # {(tv_symbol, interval): {'ts': float, 'data': dict|None}}
_TV_TA_TTL   = 20
_TV_WEBHOOK  = {}        # {SYMBOL: {'signal','price','indicator','note','ts'}}
_TV_WEBHOOK_MAX = 300
# Dual-indicator state machine: latest SuperTrend (bias) + EMA (trigger) alert per
# instrument ROOT. {ROOT: {'SUPERTREND': {...}, 'EMA': {...}}}. Drives _tv_dual_signal.
_TV_IND = {}
_TV_DEFAULT_TOKEN = os.environ.get('TV_WEBHOOK_TOKEN', '').strip() or 'mangalview'
_TV_INTERVAL = {'1m': '1', '3m': '5', '5m': '5', '15m': '15', '30m': '30',
                '1h': '60', '2h': '120', '4h': '240', '1d': '1D', '1w': '1W'}
_TV_COLS = ['Recommend.All', 'Recommend.MA', 'Recommend.Other', 'RSI', 'Mom',
            'MACD.macd', 'MACD.signal', 'Stoch.K', 'ADX', 'close']

def _tv_rating_label(v):
    try: v = float(v)
    except (TypeError, ValueError): return 'n/a'
    if v >= 0.5:  return 'STRONG BUY'
    if v >= 0.1:  return 'BUY'
    if v > -0.1:  return 'NEUTRAL'
    if v > -0.5:  return 'SELL'
    return 'STRONG SELL'

def _tv_screener_for(tv_symbol):
    pre = (tv_symbol.split(':', 1)[0] if ':' in tv_symbol else '').upper()
    if pre in ('NSE', 'BSE', 'MCX'):                                   return 'india'
    if pre in ('BINANCE', 'COINBASE', 'BYBIT', 'OKX', 'KUCOIN', 'BITSTAMP'): return 'crypto'
    if pre in ('FX', 'FX_IDC', 'OANDA', 'FOREXCOM', 'SAXO', 'PEPPERSTONE'):  return 'forex'
    if pre in ('NASDAQ', 'NYSE', 'AMEX', 'CBOE'):                      return 'america'
    return 'global'

def _tv_default_symbol(broker, symbol, exchange):
    s = (symbol or '').upper().strip()
    if not s: return ''
    if broker == 'kite':
        ex = (exchange or 'NSE').upper()
        return (ex if ex in ('NSE', 'BSE') else 'NSE') + ':' + s
    if broker == 'delta':
        base = s.replace('USDT', '').replace('USD', '')
        return 'BINANCE:' + base + 'USDT'
    if broker == 'mt5':
        return 'FX:' + s
    return s

def _tv_fetch_ta(tv_symbol, interval):
    """TradingView Technical Analysis for a symbol+interval via the public scanner.
    Returns a dict (rating + indicators) or None on any failure. Cached _TV_TA_TTL s."""
    if not tv_symbol: return None
    key = (tv_symbol, interval)
    now = _zd_time.time()
    ent = _TV_TA_CACHE.get(key)
    if ent and now - ent['ts'] < _TV_TA_TTL:
        return ent['data']
    suffix = '' if interval in ('', '1D') else '|' + interval
    cols = [c + suffix for c in _TV_COLS]
    body = __import__('json').dumps({'symbols': {'tickers': [tv_symbol], 'query': {'types': []}},
                                     'columns': cols}).encode('utf-8')
    url = 'https://scanner.tradingview.com/' + _tv_screener_for(tv_symbol) + '/scan'
    try:
        import urllib.request as _ur, json as _j
        req = _ur.Request(url, data=body, method='POST',
                          headers={'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0'})
        with _ur.urlopen(req, timeout=10) as resp:
            data = _j.loads(resp.read().decode('utf-8'))
        rows = data.get('data') or []
        if not rows:
            _TV_TA_CACHE[key] = {'ts': now, 'data': None}; return None
        m = dict(zip(_TV_COLS, rows[0].get('d') or []))
        def _f(k, nd=2):
            try: return round(float(m.get(k)), nd)
            except (TypeError, ValueError): return None
        out = {
            'tvSymbol': tv_symbol, 'interval': interval,
            'rating': _tv_rating_label(m.get('Recommend.All')), 'ratingScore': _f('Recommend.All'),
            'maRating': _tv_rating_label(m.get('Recommend.MA')),
            'oscRating': _tv_rating_label(m.get('Recommend.Other')),
            'rsi': _f('RSI', 1), 'macdHist': (round((m.get('MACD.macd') or 0) - (m.get('MACD.signal') or 0), 4)
                                              if m.get('MACD.macd') is not None else None),
            'stochK': _f('Stoch.K', 1), 'adx': _f('ADX', 1), 'close': _f('close', 4),
        }
        _TV_TA_CACHE[key] = {'ts': now, 'data': out}
        return out
    except Exception:
        _TV_TA_CACHE[key] = {'ts': now, 'data': (ent['data'] if ent else None)}
        return ent['data'] if ent else None

def _tv_context(cfg, broker, symbol, exchange):
    """TradingView context for Claude (TA + latest custom-indicator webhook), or
    None when the panel's TradingView toggle is off. Keyed under 'tradingview'."""
    if not cfg.get('tvEnabled'):
        return None
    raw_tv = (cfg.get('tvSymbol') or '').strip().upper()
    if raw_tv and ':' not in raw_tv:
        # User typed a bare symbol (e.g. BTCUSD) — TradingView needs an exchange
        # prefix, so map it through the broker default (BTCUSD -> BINANCE:BTCUSDT).
        raw_tv = _tv_default_symbol(broker, raw_tv, exchange)
    tv_symbol = raw_tv or _tv_default_symbol(broker, symbol, exchange)
    interval  = _TV_INTERVAL.get(cfg.get('tf', '5m'), '5')
    ta = _tv_fetch_ta(tv_symbol, interval)
    sym_u = (symbol or '').upper().strip()
    wh = _TV_WEBHOOK.get(sym_u) or (_TV_WEBHOOK.get(tv_symbol.split(':')[-1]) if tv_symbol else None)
    out = {'tvSymbol': tv_symbol}
    if ta:
        out.update({k: v for k, v in ta.items() if k not in ('tvSymbol', 'interval') and v is not None})
    if wh:
        out['webhook'] = {'signal': wh.get('signal'), 'indicator': wh.get('indicator'),
                          'note': wh.get('note'), 'ageSec': int(_zd_time.time()) - int(wh.get('ts', 0))}
        if wh.get('fields'):
            out['webhook']['fields'] = wh['fields']
        if wh.get('test'):
            out['webhook']['test'] = True   # manual Test-button alert — Claude must ignore for trading
    if len(out) == 1 and not wh:   # only tvSymbol, no TA and no webhook
        out['note'] = ('no TradingView data for ' + tv_symbol +
                       ' — use an EXCHANGE:SYMBOL ticker (e.g. BINANCE:BTCUSDT, NSE:RELIANCE) or leave blank for auto')
    return out

def _claude_trade_signal(symbol, candles, tf, cfg, position=None, recent_trades=None, extra_ctx=None, images=None):
    """Autonomous Claude strategy. Sends recent OHLCV plus market context (multi-
    window trend, volume/liquidity, volatility), the CURRENT position (so it
    doesn't whipsaw) and recent closed trades (so it learns) and gets a decision.
    `extra_ctx` (e.g. the underlying spot/trend for an option leg) is merged into
    the payload. Returns {name:'claude', signal, score, reason, slPct?, tpPct?}. HOLD on error."""
    if not candles or len(candles) < 20:
        return {'name': 'claude', 'signal': 'HOLD', 'score': 0.0, 'reason': 'Claude: not enough data'}
    import json as _json, re as _re
    win    = candles[-60:]
    closes = [c['close'] for c in win]
    vols   = [float(c.get('volume', 0) or 0) for c in win]
    last   = closes[-1]
    def _sma(n): return sum(closes[-n:]) / n if len(closes) >= n else (sum(closes) / len(closes))
    sma10, sma20, sma50 = _sma(10), _sma(20), _sma(50)
    trend_short = ((closes[-1] - closes[-10]) / closes[-10] * 100.0) if len(closes) >= 10 and closes[-10] else 0.0
    trend_med   = ((closes[-1] - closes[0]) / closes[0] * 100.0) if closes[0] else 0.0
    hi20 = max(c['high'] for c in win[-20:]); lo20 = min(c['low'] for c in win[-20:])
    range_pct = ((hi20 - lo20) / last * 100.0) if last else 0.0
    vol_avg    = (sum(vols[-20:]) / min(20, len(vols))) if vols else 0.0
    vol_recent = (sum(vols[-3:]) / 3.0) if len(vols) >= 3 else vol_avg
    vol_ratio  = round(vol_recent / vol_avg, 2) if vol_avg else 0.0
    # Overall trend label (the "market direction" the user wants weighed first)
    if last > sma20 > sma50 and trend_med > 0.1:   regime = 'uptrend'
    elif last < sma20 < sma50 and trend_med < -0.1: regime = 'downtrend'
    else:                                           regime = 'range/choppy'
    ohlcv = [[round(c['open'], 5), round(c['high'], 5), round(c['low'], 5), round(c['close'], 5),
              int(c.get('volume', 0) or 0)] for c in win[-36:]]

    # Support/Resistance from swing pivots (5-bar fractals) so Claude trades around
    # structure and can reason about where stop-liquidity sits (sweep/stop-hunt zones).
    sr_highs, sr_lows = [], []
    for i in range(2, len(win) - 2):
        h, l = win[i]['high'], win[i]['low']
        if h >= win[i-1]['high'] and h >= win[i-2]['high'] and h >= win[i+1]['high'] and h >= win[i+2]['high']:
            sr_highs.append(round(h, 5))
        if l <= win[i-1]['low'] and l <= win[i-2]['low'] and l <= win[i+1]['low'] and l <= win[i+2]['low']:
            sr_lows.append(round(l, 5))
    resistances = sorted({x for x in sr_highs if x >= last})[:4]
    supports    = sorted({x for x in sr_lows if x <= last}, reverse=True)[:4]
    nearest_res = min((x for x in sr_highs if x > last), default=None)
    nearest_sup = max((x for x in sr_lows if x < last), default=None)
    dist_res    = round((nearest_res - last) / last * 100.0, 2) if (nearest_res and last) else None
    dist_sup    = round((last - nearest_sup) / last * 100.0, 2) if (nearest_sup and last) else None

    pos_ctx = None
    if position:
        ep = position.get('entryPrice') or 0
        side = position.get('side')
        unreal_pct = (((last - ep) / ep * 100.0) * (1 if side == 'BUY' else -1)) if ep else 0.0
        pos_ctx = {'side': side, 'entryPrice': ep, 'unrealizedPct': round(unreal_pct, 2)}
    trades_ctx = [{'side': t.get('side'), 'pnl': round(t.get('pnl', 0), 2), 'reason': t.get('reason')}
                  for t in (recent_trades or [])[-8:]]
    wins = sum(1 for t in trades_ctx if t['pnl'] > 0)

    # OPTIONS block — only when this instrument is an option leg. Covers BOTH
    # buying (long premium) and selling/shorting (harvesting theta + IV crush).
    option_block = ""
    if extra_ctx and extra_ctx.get('optionType'):
        buyer_on  = extra_ctx.get('buyerEnabled', True)
        seller_on = extra_ctx.get('sellerEnabled', False)
        if buyer_on and seller_on:
            allowed = ("BOTH are enabled: BUY (go LONG the option) and SELL (go SHORT / sell the option) are both "
                       "valid — choose whichever has the genuine edge, else HOLD.")
        elif seller_on:
            allowed = ("ONLY SELL (short / sell the option to collect decay) is enabled — return SELL to short or "
                       "HOLD. Do NOT return BUY.")
        else:
            allowed = ("ONLY BUY (go long the option) is enabled — return BUY to go long or HOLD. Do NOT return SELL.")
        option_block = (
            "\nOPTIONS — READ CAREFULLY. 'symbol' is an OPTION (optionType: CE=call, PE=put) on the underlying; the "
            "OHLCV/price shown is the OPTION PREMIUM, not the index. " + allowed + "\n"
            "SIGNAL MEANING for an option leg: BUY = go LONG the option, you profit if the PREMIUM RISES. "
            "SELL = go SHORT / SELL the option, you profit if the PREMIUM FALLS (time decay, IV/volatility crush, or "
            "the underlying moving against the option).\n"
            "PREMIUM = intrinsic + extrinsic(time + IV). Extrinsic is destroyed by: (a) THETA / TIME DECAY — fastest "
            "for OTM and low-DTE options, accelerates intraday; (b) IV CRUSH — implied volatility collapses after the "
            "volatile open and after events, so premiums fall even when the index is flat; (c) DIRECTION — a CE bleeds "
            "when the underlying falls/stalls, a PE bleeds when it rises/stalls.\n"
            "BUYER (BUY / long) — take ONLY when the premium will likely EXPAND: a FRESH directional thrust in the "
            "option's favour (CE = underlying breaking UP with momentum + rising volume; PE = underlying breaking "
            "DOWN) and IV is NOT collapsing. NEVER buy a bleeding or mid-range premium into a flat/opposing underlying "
            "— theta + IV crush will melt it (the classic morning-buyer trap). Demand a real underlying move, R:R>=1.5.\n"
            "SELLER (SELL / short) — collect decay when the premium is RICH and likely to FALL: choppy/range-bound or "
            "OPPOSING underlying (both CE and PE bleed when the index goes nowhere), post-open IV crush, or OTM strikes "
            "the underlying is unlikely to reach. Prefer OTM, lower DTE, elevated/just-spiked premium. This is a "
            "HIGH-PROBABILITY theta trade and CAN score >=7 in a flat/choppy regime — do NOT just HOLD a clearly "
            "decaying premium when SELL is enabled; that is leaving the edge on the table.\n"
            "SHORT-OPTION RISK IS LARGE/UNDEFINED: a short loses fast if the underlying trends toward/through the "
            "strike (CE: index rallies; PE: index drops) or IV spikes. So for a SELL set a TIGHT slPct = the premium % "
            "RISE that stops you out (e.g. 25-40%), and tpPct = the premium % DROP you target (the decay you expect). "
            "Exit at once if the underlying starts trending in the option's favour.\n"
            "SELLER GUARDRAILS (avoid the morning trap that loses big): do NOT short HIGH/rich ATM premium early in the "
            "session or when gamma is high — a small index move can DOUBLE the premium and blow the stop (a CE shorted "
            "at ~60 ran to ~103 = a full stop-out). Prefer premium that is ALREADY decaying (price below sma10/sma20), "
            "OTM or just-OTM strikes, and the back half of the session. Require the underlying to be flat or moving "
            "AGAINST the option (use underlyingVsStrikePct + underlyingTrendPct), not merely 'theta exists'. SKIP "
            "micro-premium shorts (premium < ~3): the decay left is pennies but a spike still stops you out — bad "
            "reward:risk and not worth the tail risk.\n"
            "Weigh optionType, moneyness, underlyingVsStrikePct, dte and underlyingTrendPct together before deciding.\n"
        )

    # TradingView block — external confirmation (context only) when the panel's
    # TradingView toggle is on. Claude still decides; TV nudges conviction.
    tv_block = ""
    if extra_ctx and extra_ctx.get('tradingview'):
        tv_block = (
            "\nTRADINGVIEW (external confirmation in 'tradingview'): 'rating' is TradingView's overall technical "
            "signal (STRONG BUY..STRONG SELL) from its standard indicators, with rsi / macdHist / stochK / adx and "
            "the moving-average (maRating) and oscillator (oscRating) ratings. 'webhook' (if present) is the user's "
            "OWN custom-indicator alert — signal + indicator + ageSec, plus any extra values the indicator sent in "
            "webhook.fields (e.g. its RSI/plots/SL/TP). WEIGH all of these as confirmation: lift conviction "
            "when they ALIGN with your read, and lower it / raise your bar when they OPPOSE it. A fresh webhook "
            "(small ageSec) is a strong hint; a stale one (large ageSec) is weak. This is confirmation ONLY — you "
            "still make the final call; never trade against your own structure read just because TV disagrees. "
            "If webhook.test is true it is a MANUAL TEST alert — IGNORE it completely, do not let it influence the trade.\n")

    min_enter = float(cfg.get('minScore', 0) or 0) + float(cfg.get('scoreBuffer', 0) or 0)
    if min_enter <= 0:
        gate = ("Score the setup YOURSELF on a 0-10 conviction scale and ONLY take BUY/SELL when your own conviction "
                "is genuinely HIGH (>=7); otherwise HOLD. A high win rate comes from passing on mediocre setups — "
                "when in doubt, HOLD.")
    else:
        gate = ("Only choose BUY or SELL when your conviction |score| >= " + str(min_enter) + " (score sign matches signal).")
    # Operator note: the user's latest chat message is stored on the config and fed to
    # the live decision loop as guidance (a bias, a level, "only longs", "stay flat"…).
    note_txt, note_age = '', None
    _note = cfg.get('userNote') or {}
    if isinstance(_note, dict) and _note.get('text'):
        note_age = int(_zd_time.time()) - int(_note.get('ts', 0) or 0)
        if note_age <= 3600:                       # honour it for 1h
            note_txt = str(_note['text'])[:400]
        else:
            note_age = None
    system = (
        "You are an ELITE intraday trader. Your job: make the MAXIMUM profit with a HIGH WIN RATE so the customer is "
        "happy. Trade like a professional reading order flow and market-maker (smart-money) behaviour — NOT a "
        "retail breakout-chaser. Be highly selective: a few high-quality trades beat many mediocre ones.\n"
        "METHOD (in order):\n"
        "1) MARKET DIRECTION: read the higher-timeframe trend from regime/SMAs/trend%. Trade WITH the trend. In a "
        "'range/choppy' regime default to HOLD unless price is reacting at a clean support/resistance level.\n"
        "2) STRUCTURE (support/resistance): use 'supports'/'resistances' and the nearest levels. BUY near SUPPORT in "
        "an uptrend; SELL near RESISTANCE in a downtrend. NEVER buy straight into resistance or sell straight into "
        "support — that is where moves stall and reverse. Best entries are AT structure, not mid-range.\n"
        "3) MARKET-MAKER / SMART MONEY: anticipate liquidity. Market makers run price into obvious stop clusters just "
        "beyond recent swing highs/lows (liquidity grabs / stop hunts), then reverse. A sweep of a level that "
        "IMMEDIATELY reclaims is a high-probability reversal entry in the reclaim direction. Do NOT be the liquidity: "
        "avoid chasing a breakout that just swept a level on a long wick — wait for the reclaim/retest. Favour "
        "entries where the stops are BEHIND your invalidation (so the next stop-run pushes your trade into profit).\n"
        "4) CONFIRMATION: require participation — rising volume (volRatio > 1.1) on the move you trade. Weak/declining "
        "volume = whipsaw; HOLD.\n"
        "5) ANTI-WHIPSAW: if you already hold a 'position', DEFAULT to staying (HOLD to keep, or same-direction). Only "
        "flip on a genuine structural reversal (level break + reclaim against you). Do NOT flip on noise — costs add up.\n"
        "6) LEARN: review 'recentTrades'. If recent trades lost in conditions like now (esp. 'signal reversal' exits), "
        "be MORE selective and HOLD more.\n"
        "RISK: You OWN risk management — ALWAYS set slPct and tpPct (percent from entry). Put SL just BEYOND the "
        "invalidation level (the swing/structure that proves you wrong), and TP at the next opposing S/R level, with "
        "reward:risk >= 1.5. These override the panel's SL/TP. Never omit them on a BUY/SELL.\n"
        "VOLATILITY & SLIPPAGE: the stop is enforced on candle data, so a single violent bar can slip past it. In "
        "fast/high-volatility conditions (very wide recent bars, range expanding fast, volRatio >> 1.5 on a runaway "
        "move) do NOT chase — HOLD, or demand a tighter structure-based stop. Keep slPct tight: if the only valid "
        "invalidation sits far away (a wide stop), the trade risks too much per unit — prefer HOLD. After a recent "
        "'SL hit' loss in conditions like now, RAISE your bar and be more selective (HOLD more).\n"
        + option_block
        + tv_block
        + (("IMAGE ATTACHED: A screenshot is attached — it may be a PRICE CHART (SuperTrend/EMA/PSAR/"
            "support-resistance, often multiple timeframes) and/or OPTION-CHAIN / OPEN-INTEREST (OI) / max-pain "
            "data. Read whatever it shows and treat it as the PRIMARY read: from a chart take trend, key S/R and "
            "indicator alignment; from OI/option-chain data infer support/resistance from high-OI strikes, PCR, OI "
            "build-up vs unwinding, and the likely pin / max-pain level — then align your decision (and, for "
            "options, the strike & side) with it. If the image contradicts the numeric fields, trust the image. It "
            "is the user's latest manual view — weight it heavily.\n")
           if images else "")
        + (("OPERATOR NOTE: 'operatorNote' is the user's latest instruction/context typed in the chat "
            "(e.g. a directional bias, a level to watch, 'only longs today', 'stay flat', 'be aggressive'). "
            "FACTOR IT INTO your decision and strike/side. It is guidance, not a hard override — you still own "
            "risk and may HOLD if the setup is poor. Treat an older note (large operatorNoteAgeSec) as weaker.\n")
           if note_txt else "")
        + "Respond with STRICT JSON ONLY, no prose: {\"signal\":\"BUY\"|\"SELL\"|\"HOLD\",\"score\":<-10..10>,"
        "\"fcastPct\":<your forecast of the % price move over the next ~5-10 bars; + up / - down, e.g. 0.6 or -1.2>,"
        "\"reason\":\"<=160 chars, mention trend+why\",\"slPct\":<optional>,\"tpPct\":<optional>}. " + gate
    )
    _payload = {
        'symbol': symbol, 'tf': tf, 'regime': regime, 'lastPrice': round(last, 5),
        'sma10': round(sma10, 5), 'sma20': round(sma20, 5), 'sma50': round(sma50, 5),
        'trendShortPct': round(trend_short, 2), 'trendMediumPct': round(trend_med, 2),
        'rangePct20': round(range_pct, 2), 'recentHigh20': round(hi20, 5), 'recentLow20': round(lo20, 5),
        'supports': supports, 'resistances': resistances,
        'nearestSupport': nearest_sup, 'nearestResistance': nearest_res,
        'distToSupportPct': dist_sup, 'distToResistancePct': dist_res,
        'volAvg20': round(vol_avg, 1), 'volRecent3': round(vol_recent, 1), 'volRatio': vol_ratio,
        'position': pos_ctx, 'recentTrades': trades_ctx, 'recentWinRate': (round(wins/len(trades_ctx)*100) if trades_ctx else None),
        'ohlcv': ohlcv,
    }
    if note_txt:
        _payload['operatorNote'] = note_txt
        _payload['operatorNoteAgeSec'] = note_age
    if extra_ctx:
        _payload.update(extra_ctx)
    user = _json.dumps(_payload, default=str)
    text, err = _call_claude(system, [{'role': 'user', 'content': user}], max_tokens=400, model=cfg.get('model'), images=images)
    if err:
        return {'name': 'claude', 'signal': 'HOLD', 'score': 0.0, 'reason': 'Claude unavailable: ' + err[:220]}
    sig, score, reason, sl_pct, tp_pct, fcast = 'HOLD', 0.0, '', None, None, None
    try:
        m = _re.search(r'\{.*\}', text or '', _re.DOTALL)
        obj = _json.loads(m.group(0)) if m else {}
        sig = str(obj.get('signal', 'HOLD')).upper()
        if sig not in ('BUY', 'SELL', 'HOLD'): sig = 'HOLD'
        score = float(obj.get('score', 0) or 0)
        reason = str(obj.get('reason', ''))[:180]
        if obj.get('fcastPct') is not None:
            fcast = max(-99.0, min(99.0, float(obj.get('fcastPct'))))
        if obj.get('slPct') is not None:
            sl_pct = min(50.0, max(0.2, float(obj.get('slPct'))))
        if obj.get('tpPct') is not None:
            tp_pct = min(50.0, max(0.2, float(obj.get('tpPct'))))
    except Exception:
        sig, score, reason = 'HOLD', 0.0, 'parse error: ' + (text or '')[:80]
    # Prepend the next-move forecast so it shows in every entry log / tick / journal.
    tag = ('f{:+.1f}% '.format(fcast)) if fcast is not None else ''
    out = {'name': 'claude', 'signal': sig, 'score': score, 'reason': 'Claude: ' + tag + reason}
    if fcast is not None: out['fcastPct'] = fcast
    if sl_pct is not None: out['slPct'] = sl_pct
    if tp_pct is not None: out['tpPct'] = tp_pct
    return out

# Curated liquid universes for Auto-Symbol mode (Claude picks from these).
_BOT_UNIVERSE = {
    'delta': ['BTCUSD', 'ETHUSD', 'SOLUSD', 'BNBUSD', 'XRPUSD', 'AVAXUSD'],
    'kite':  ['RELIANCE', 'HDFCBANK', 'ICICIBANK', 'INFY', 'TCS', 'SBIN', 'TATAMOTORS'],
    'mt5':   ['EURUSD', 'GBPUSD', 'USDJPY', 'XAUUSD', 'AUDUSD', 'USDCAD'],
}

def _bot_candidates(source, cfg):
    """Symbols scanned when flat: Auto-Symbol → curated universe; else the user
    watchlist; else the single configured symbol."""
    if cfg.get('autoSymbol'):
        return list(_BOT_UNIVERSE.get(source, []))
    syms = [s for s in (cfg.get('symbols') or []) if s]
    if syms:
        return syms
    s = (cfg.get('symbol') or '').strip()
    return [s] if s else []

def _bot_pick_symbol(state, cfg, source):
    """1-position-at-a-time autopilot: while FLAT, round-robin the active symbol
    across candidates so Claude scans one per tick. While IN a trade, keep the
    position's symbol (set cfg['symbol']) so management/close use the right one."""
    if state.get('position'):
        return
    cands = _bot_candidates(source, cfg)
    if not cands:
        return
    idx = int(state.get('scan_idx', 0)) % len(cands)
    cfg['symbol'] = cands[idx].upper()
    state['scan_idx'] = idx + 1

_DELTA_GAINERS_CACHE = {'ts': 0.0, 'data': []}
def _delta_top_gainers(n=8):
    """Top-gaining Delta perpetuals by 24h change (decent volume). Cached 5 min.
    Used by the Delta bot's 'Tokens' mode to chase high-momentum movers."""
    now = _zd_time.time()
    if now - _DELTA_GAINERS_CACHE['ts'] < 300 and _DELTA_GAINERS_CACHE['data']:
        return _DELTA_GAINERS_CACHE['data']
    rows = None
    for base in _DELTA_BASES:
        resp = _delta_get_public('/v2/tickers', base_url=base)
        if resp.get('success'):
            rows = resp.get('result') or []
            break
    if not rows:
        return _DELTA_GAINERS_CACHE['data']
    items = []
    for t in rows:
        sym = (t.get('symbol') or '').upper()
        if not sym or not (sym.endswith('USD') or sym.endswith('USDT')):
            continue
        ctype = (t.get('contract_type') or '').lower()
        if ctype and 'perpetual' not in ctype:   # perps only (skip options/spot/futures)
            continue
        try:    chg = float(t.get('mark_change_24h') if t.get('mark_change_24h') is not None else (t.get('change_24h') or 0))
        except (TypeError, ValueError): chg = 0.0
        try:    vol = float(t.get('turnover_usd') or t.get('turnover') or t.get('volume') or 0)
        except (TypeError, ValueError): vol = 0.0
        if vol <= 0:
            continue
        items.append((sym, chg, vol))
    if not items:
        return _DELTA_GAINERS_CACHE['data']
    # require some liquidity (top half by volume), then rank by 24h gain
    items.sort(key=lambda x: x[2], reverse=True)
    liquid = items[:max(n * 4, 20)]
    liquid.sort(key=lambda x: x[1], reverse=True)
    syms = [s for s, _, _ in liquid[:n]]
    if syms:
        _DELTA_GAINERS_CACHE.update({'ts': now, 'data': syms})
    return syms

def _claude_auto_pick(source, interval, cfg, api_key, recent_trades):
    """Auto-symbol mode: in ONE Claude call, scan the universe and return the
    SINGLE best symbol to trade now PLUS the trade decision. Returns a strat dict
    {name, symbol, signal, score, reason, slPct?, tpPct?} (HOLD on any issue)."""
    import json as _json, re as _re
    if source == 'delta' and cfg.get('tokens'):
        universe = _delta_top_gainers() or _BOT_UNIVERSE.get('delta', [])
    else:
        universe = _BOT_UNIVERSE.get(source, [])
    cands = []
    for sym in universe:
        try:
            c = _bot_fetch_candles(sym, interval, source, api_key=api_key)
        except Exception:
            c = []
        if not c or len(c) < 15:
            continue
        cl = [x['close'] for x in c[-30:]]
        vols = [float(x.get('volume', 0) or 0) for x in c[-20:]]
        last = cl[-1]
        cands.append({
            'symbol': sym, 'last': round(last, 5),
            'trendShortPct': round((cl[-1]-cl[-10])/cl[-10]*100.0, 2) if len(cl) >= 10 and cl[-10] else 0.0,
            'trendMedPct':   round((cl[-1]-cl[0])/cl[0]*100.0, 2) if cl[0] else 0.0,
            'rangePct':      round((max(x['high'] for x in c[-20:]) - min(x['low'] for x in c[-20:]))/last*100.0, 2) if last else 0.0,
            'volRatio':      round((sum(vols[-3:])/3.0)/(sum(vols)/max(1, len(vols))), 2) if vols and sum(vols) > 0 else 0.0,
            'ohlc': [[round(x['open'], 5), round(x['high'], 5), round(x['low'], 5), round(x['close'], 5)] for x in c[-15:]],
        })
    if not cands:
        return {'name': 'claude', 'signal': 'HOLD', 'score': 0.0, 'reason': 'Claude: no market data', 'symbol': cfg.get('symbol', '')}
    trades_ctx = [{'sym': t.get('symbol'), 'pnl': round(t.get('pnl', 0), 4), 'reason': t.get('reason')} for t in (recent_trades or [])[-6:]]
    cap = cfg.get('capital')
    system = (
        "You are an autonomous trader. From the candidate instruments below, pick the SINGLE BEST one to trade RIGHT "
        "NOW for a high win rate — weigh trend strength, volatility and liquidity (volRatio). Then give the trade "
        "decision for that one symbol. Prefer HOLD (no trade) if none has a clear edge; do not force a trade in chop. "
        "Set slPct/tpPct from structure for a strong reward:risk. Also choose a SAFE leverage 1-20 (LOWER in high "
        "volatility) used to size the position from capital. Respond STRICT JSON ONLY: {\"symbol\":\"..\",\"signal\":"
        "\"BUY\"|\"SELL\"|\"HOLD\",\"score\":<-10..10>,\"reason\":\"<=160 chars\",\"slPct\":<optional>,\"tpPct\":"
        "<optional>,\"leverage\":<1-20>}.")
    user = _json.dumps({'candidates': cands, 'recentTrades': trades_ctx, 'capitalUSD': cap}, default=str)
    text, err = _call_claude(system, [{'role': 'user', 'content': user}], max_tokens=400, model=cfg.get('model'))
    if err:
        return {'name': 'claude', 'signal': 'HOLD', 'score': 0.0, 'reason': 'Claude unavailable: ' + err[:160], 'symbol': cands[0]['symbol']}
    try:
        obj = _json.loads(_re.search(r'\{.*\}', text or '', _re.DOTALL).group(0))
        valid = {c['symbol'] for c in cands}
        sym = str(obj.get('symbol', '')).upper()
        if sym not in valid:
            sym = cands[0]['symbol']
        sig = str(obj.get('signal', 'HOLD')).upper()
        if sig not in ('BUY', 'SELL', 'HOLD'): sig = 'HOLD'
        out = {'name': 'claude', 'symbol': sym, 'signal': sig, 'score': float(obj.get('score', 0) or 0),
               'reason': 'Claude(auto→' + sym + '): ' + str(obj.get('reason', ''))[:180]}
        if obj.get('slPct') is not None: out['slPct'] = min(50.0, max(0.2, float(obj['slPct'])))
        if obj.get('tpPct') is not None: out['tpPct'] = min(50.0, max(0.2, float(obj['tpPct'])))
        if obj.get('leverage') is not None: out['leverage'] = min(20.0, max(1.0, float(obj['leverage'])))
        return out
    except Exception:
        return {'name': 'claude', 'signal': 'HOLD', 'score': 0.0, 'reason': 'Claude: parse error', 'symbol': cands[0]['symbol']}

# --- Position management (caller must hold delta_ai_lock) ---
def _delta_bot_open(side, price, strat, mode):
    cfg    = delta_ai_state['config']
    # Capital-based auto sizing: qty = capital × leverage ÷ (price × contract_value).
    # Leverage = the panel's manual value or Claude's pick (1-125x); falls back to the
    # Qty field if no capital. Matches the Leverage button's preview.
    capital = float(cfg.get('capital') or 0)
    lev     = min(125.0, max(1.0, float(strat.get('leverage') or cfg.get('leverage') or 5)))
    if capital > 0 and price > 0:
        prod = _load_delta_products().get((cfg.get('symbol') or '').upper())
        cv   = float((prod or {}).get('contract_value', 1.0) or 1.0)
        qty  = max(1, int((capital * lev) / (price * cv)))
        cfg['leverage'] = lev
    else:
        qty = int(cfg.get('qty', 1))
    sl_pct = float(strat.get('slPct') or cfg.get('slPct', 1.0))   # Claude can set its own SL/TP
    tp_pct = float(strat.get('tpPct') or cfg.get('tpPct', 2.0))
    sl = price * (1 - sl_pct/100.0) if side == 'BUY' else price * (1 + sl_pct/100.0)
    tp = price * (1 + tp_pct/100.0) if side == 'BUY' else price * (1 - tp_pct/100.0)
    # LIVE: place first; open the internal position ONLY if the exchange accepted the
    # order. A rejected entry must NOT create a phantom position (which would later fire
    # a REAL exit and could close a trade you placed manually).
    if mode == 'live':
        if not _delta_bot_place_live(side, qty, cfg):
            _bot_log('[LIVE] ENTRY REJECTED — no position opened for {} ({} {}).'.format(cfg.get('symbol'), side, qty))
            _persist_log_line('[DELTA] [LIVE] ENTRY REJECTED — no position opened ' + str(cfg.get('symbol')))
            return
    delta_ai_state['position'] = {
        'side': side, 'entryPrice': price, 'entryTime': int(_zd_time.time()),
        'qty': qty, 'sl': round(sl, 4), 'tp': round(tp, 4),
        'slPct': sl_pct, 'tpPct': tp_pct,   # kept for TP-continuation re-entry
        'strategy': strat['name'], 'mode': mode,
    }
    tag  = '[DELTA-' + mode.upper() + ']'
    _cap_note = (' [cap $' + str(capital) + ' ×' + str(lev) + 'x]') if capital > 0 else ''
    line = '{} ENTRY {} {} {} @ {} SL={} TP={} strat={} score={:.1f}{} — {}'.format(
        tag, side, qty, cfg['symbol'], price, round(sl, 4), round(tp, 4),
        strat['name'], strat['score'], _cap_note, strat.get('reason', ''))
    _bot_log(line)
    _persist_log_line('[DELTA] ' + line)

def _delta_calc_pnl(entry, exit_, qty, side, product):
    """Approximate P/L for a Delta contract.
    - Vanilla:  pnl = (exit - entry) * qty * contract_value * direction
    - Inverse:  pnl = qty * contract_value * (1/entry - 1/exit) * direction
    Returns float in the settling-asset currency (USDT/USD). Doesn't include
    fees or funding — for exact P/L use /v2/positions (sync'd in LIVE mode)."""
    if not entry or not exit_ or not qty: return 0.0
    direction = 1 if side == 'BUY' else -1
    cv = float((product or {}).get('contract_value', 1.0) or 1.0)
    ntype = ((product or {}).get('notional_type') or 'vanilla').lower()
    try:
        if ntype == 'inverse':
            return qty * cv * (1.0/float(entry) - 1.0/float(exit_)) * direction
        else:
            return (float(exit_) - float(entry)) * qty * cv * direction
    except Exception:
        return 0.0

def _delta_bot_close(price, reason, mode):
    pos = delta_ai_state.get('position')
    if not pos: return
    direction = 1 if pos['side'] == 'BUY' else -1
    # Look up the contract spec to scale P/L correctly. For 1 BTCUSD contract
    # on Delta India this is 0.001 — without it, a $580 price move shows up
    # as -$580 P/L when actual settlement is -$0.58.
    sym_u    = delta_ai_state['config']['symbol'].upper()
    products = _load_delta_products()
    prod     = products.get(sym_u)
    pnl      = _delta_calc_pnl(pos['entryPrice'], price, pos['qty'], pos['side'], prod)
    closed = dict(pos)
    closed.update({'exitPrice': round(price, 4), 'exitTime': int(_zd_time.time()),
                   'pnl': round(pnl, 4), 'reason': reason})
    delta_ai_state['trades'].append(closed)
    if pnl < 0: delta_ai_state['consec_losses'] = delta_ai_state.get('consec_losses', 0) + 1
    else:       delta_ai_state['consec_losses'] = 0
    cfg = delta_ai_state['config']
    tag = '[DELTA-' + mode.upper() + ']'
    line = '{} EXIT {} {} {} @ {} (entry {}) PnL={}{:.4f} reason={} strat={}'.format(
        tag, 'SELL' if pos['side'] == 'BUY' else 'BUY',
        pos['qty'], cfg['symbol'], price, pos['entryPrice'],
        '+' if pnl >= 0 else '', pnl, reason, pos['strategy'])
    _bot_log(line)
    _persist_log_line('[DELTA] ' + line)
    if mode == 'live':
        _delta_bot_place_live('SELL' if pos['side'] == 'BUY' else 'BUY', pos['qty'], cfg)
    delta_ai_state['position'] = None
    delta_ai_state['last_exit_time'] = int(_zd_time.time())
    # Circuit breakers
    realized   = sum(t['pnl'] for t in delta_ai_state['trades'])
    max_consec = int(cfg.get('maxConsec', 3))
    max_loss   = float(cfg.get('maxLoss', 200))
    max_profit = float(cfg.get('maxProfit', 0) or 0)
    if delta_ai_state['consec_losses'] >= max_consec:
        _bot_log('[STOP] Max consecutive losses ({}) reached. Bot stopped.'.format(max_consec))
        _persist_log_line('[DELTA] [STOP] Max consecutive losses')
        delta_ai_state['running'] = False
    elif realized < -abs(max_loss):
        _bot_log('[STOP] Max daily loss {} breached (realised {:.2f}). Bot stopped.'.format(max_loss, realized))
        _persist_log_line('[DELTA] [STOP] Max daily loss')
        delta_ai_state['running'] = False
    elif max_profit > 0 and realized >= max_profit:
        _bot_log('[STOP] Max daily profit {} hit (realised {:.2f}). Trade closed, bot stopped.'.format(max_profit, realized))
        _persist_log_line('[DELTA] [STOP] Max daily profit')
        delta_ai_state['running'] = False

def _delta_bot_place_live(side, qty, cfg):
    """Place a live Delta order. Returns True only if the exchange ACCEPTED it."""
    api_key = cfg.get('api_key') or ''
    if not api_key or api_key not in delta_v2_sessions:
        _bot_log('[LIVE] Delta order skipped — not connected.')
        _persist_log_line('[DELTA] [LIVE] order skipped: not connected')
        return False
    products = _load_delta_products()
    p = products.get(cfg['symbol'].upper())
    if not p or not p.get('id'):
        _bot_log('[LIVE] Unknown Delta symbol: ' + cfg['symbol'])
        return False
    api_secret = delta_v2_sessions[api_key]['api_secret']
    sess_base  = delta_v2_sessions[api_key].get('base_url') or _DELTA_BASES[0]
    body = {
        'product_id': p['id'], 'size': qty,
        'side': 'buy' if side == 'BUY' else 'sell',
        'order_type': 'market_order',
    }
    result = _delta_request(api_key, api_secret, 'POST', '/v2/orders', body=body, base_url=sess_base)
    if result.get('success'):
        oid = (result.get('result') or {}).get('id', '')
        _bot_log('[LIVE] Delta accepted #' + str(oid))
        _persist_log_line('[DELTA] [LIVE] Delta accepted #' + str(oid))
        return True
    err = result.get('error', 'unknown')
    _bot_log('[LIVE] Delta order failed: ' + str(err))
    _persist_log_line('[DELTA] [LIVE] Delta order failed: ' + str(err))
    return False

def _delta_bot_tick():
    cfg = delta_ai_state.get('config') or {}
    if not cfg: return
    interval = cfg.get('tf', '5m')
    # Auto-symbol: while flat, Claude picks the SINGLE best symbol (+ decision).
    _autopick = (_claude_auto_pick('delta', interval, cfg, None, delta_ai_state.get('trades'))
                 if (_bot_is_claude(cfg) and (cfg.get('autoSymbol') or cfg.get('tokens')) and not delta_ai_state.get('position')
                     and delta_ai_state.get('_decide', True)) else None)
    if _autopick is not None:
        cfg['symbol'] = (_autopick.get('symbol') or cfg.get('symbol') or '').upper()
    else:
        _bot_pick_symbol(delta_ai_state, cfg, 'delta')   # watchlist round-robin / hold position symbol
    symbol   = (cfg.get('symbol') or '').upper()
    if not symbol: return

    try:
        candles = _bot_fetch_candles(symbol, interval, 'delta')
    except Exception as e:
        _bot_log('[Tick] ERROR fetching data: ' + str(e))
        return
    if not candles:
        with delta_ai_lock:
            delta_ai_state['last_tick'] = {'time': int(_zd_time.time()), 'error': 'no candles'}
        _bot_log('[Tick] no Delta candles for ' + symbol)
        return

    price  = candles[-1]['close']
    regime = _bot_detect_regime(candles)
    if _autopick is not None:
        strat = _autopick
    elif _bot_is_claude(cfg) and delta_ai_state.get('_decide', True):
        _tv = _tv_context(cfg, 'delta', symbol, '')
        strat = _claude_trade_signal(symbol, candles, interval, cfg, delta_ai_state.get('position'), delta_ai_state.get('trades'),
                                     extra_ctx=({'tradingview': _tv} if _tv else None),
                                     images=_chart_images_for(delta_ai_state))
    elif _bot_is_claude(cfg):
        strat = {'name': 'claude', 'signal': 'HOLD', 'score': 0.0, 'reason': '(holding between decisions)'}
    else:
        strat = _tv_alert_signal(delta_ai_state, cfg, symbol)   # Claude off -> trade TV alerts
    mode   = cfg.get('mode', 'paper')

    # --- LIVE mode: pull authoritative position/P&L from Delta ---
    # Delta's /v2/positions response carries the exact unrealized_pnl and
    # realized_pnl (after fees, funding, contract math). Trust that over our
    # local approximation when running live. Also catches manual square-off /
    # liquidation done outside our bot.
    delta_live_pos = None
    delta_live_realized = None
    if mode == 'live':
        ak = cfg.get('api_key')
        if ak and ak in delta_v2_sessions:
            try:
                sess_base = delta_v2_sessions[ak].get('base_url') or _DELTA_BASES[0]
                api_sec   = delta_v2_sessions[ak]['api_secret']
                pos_resp  = _delta_request(ak, api_sec, 'GET', '/v2/positions/margined', base_url=sess_base)
                if not pos_resp.get('success'):
                    pos_resp = _delta_request(ak, api_sec, 'GET', '/v2/positions', base_url=sess_base)
                sym_u = symbol.upper()
                for p in (pos_resp.get('result') or []):
                    psym = ((p.get('product') or {}).get('symbol') or p.get('symbol', '')).upper()
                    if psym == sym_u:
                        delta_live_pos = {
                            'size': int(p.get('size', 0) or 0),
                            'entry_price': float(p.get('entry_price', 0) or 0),
                            'mark_price':  float(p.get('mark_price',  0) or 0),
                            'unrealized_pnl': float(p.get('unrealized_pnl', 0) or 0),
                            'realized_pnl':   float(p.get('realized_pnl', 0) or 0),
                            'liquidation_price': float(p.get('liquidation_price', 0) or 0),
                        }
                        break
            except Exception:
                pass

    er      = _bot_efficiency_ratio(candles, cfg)
    er_tag  = _bot_er_tag(candles, cfg)
    with delta_ai_lock:
        delta_ai_state['last_candles'] = candles[-150:]
        delta_ai_state['last_tick'] = {
            'time': int(_zd_time.time()), 'price': price,
            'strategy': strat['name'], 'signal': strat['signal'],
            'score': strat['score'], 'reason': strat['reason'],
            'regime': '{} vol, {} · {}'.format(regime['volatility'],
                'trending ' + regime['direction'] if regime['trending'] else 'range', er_tag),
            'er': er, 'ranging': _bot_is_ranging(candles, cfg),
            # Live values from Delta (when available) — used by /status for display
            'delta_live': delta_live_pos,
        }
        # If LIVE and Delta shows our position is closed (size=0), treat it
        # as an external exit and let the bot resume looking for entries.
        if mode == 'live' and delta_live_pos is not None:
            if delta_live_pos['size'] == 0 and delta_ai_state.get('position'):
                ext_pnl = delta_live_pos.get('realized_pnl', 0.0)
                _bot_log('[Position] {} closed externally on Delta (realised P/L per Delta: {:+.4f})'.format(symbol, ext_pnl))
                _persist_log_line('[DELTA] [Position] {} closed externally — Delta realised={:+.4f}'.format(symbol, ext_pnl))
                # Record the close with Delta's PnL to keep stats accurate
                pos_local = delta_ai_state['position']
                closed = dict(pos_local)
                closed.update({'exitPrice': round(price, 4), 'exitTime': int(_zd_time.time()),
                               'pnl': round(ext_pnl, 4), 'reason': 'external close (Delta)'})
                delta_ai_state['trades'].append(closed)
                if ext_pnl < 0: delta_ai_state['consec_losses'] = delta_ai_state.get('consec_losses', 0) + 1
                else:            delta_ai_state['consec_losses'] = 0
                delta_ai_state['position'] = None
        pos = delta_ai_state.get('position')
        # --- Manual override (Open/Close buttons): runs before the signal logic ---
        mcmd = delta_ai_state.pop('manualCmd', None)
        if mcmd:
            _maction = (mcmd.get('action') or '').lower(); _mside = mcmd.get('side')
            if _maction == 'close':
                if pos:
                    _bot_log('[Manual] [delta] close {} @ {}'.format(symbol, price))
                    _delta_bot_close(price, 'manual close', mode)
                else:
                    _bot_log('[Manual] [delta] close ignored — no open position')
            elif _maction == 'open' and _mside in ('BUY', 'SELL'):
                if pos and pos['side'] == _mside:
                    _bot_log('[Manual] [delta] open {} ignored — already {}'.format(_mside, pos['side']))
                else:
                    if pos:
                        _bot_log('[Manual] [delta] reverse — close {} then open {}'.format(pos['side'], _mside))
                        _delta_bot_close(price, 'manual reverse', mode)
                    _ms = {'name': 'manual', 'signal': _mside, 'score': 10.0, 'seed': True,
                           'reason': 'manual open ' + _mside}
                    _ms.update(_seed_sltp(cfg, symbol))   # SL capped — never the 5% panel default
                    _bot_log('[Manual] [delta] open {} {} @ {}'.format(_mside, symbol, price))
                    _delta_bot_open(_mside, price, _ms, mode)
                    if delta_ai_state.get('position'):
                        delta_ai_state['position']['entryBarTime'] = candles[-1].get('time')
            return   # manual action stands for this tick; normal logic resumes next tick
        if pos:
            is_long = pos['side'] == 'BUY'
            # Profit-lock: if total P/L (realised + this position's unrealised)
            # has reached the daily profit target, bank it and stop.
            max_profit = float(cfg.get('maxProfit', 0) or 0)
            reason = None
            if max_profit > 0:
                realized_now = sum(t.get('pnl', 0) for t in delta_ai_state['trades'])
                prod_now     = _load_delta_products().get(symbol.upper())
                unreal_now   = _delta_calc_pnl(pos['entryPrice'], price, pos['qty'], pos['side'], prod_now)
                if realized_now + unreal_now >= max_profit:
                    reason = 'max daily profit'
            exit_px = price
            if reason is None:
                # Intrabar stop/target — but on the ENTRY bar use close only (high/low
                # may predate the fill), to avoid false SL/TP and TP-re-entry loops.
                bar = candles[-1]
                if bar.get('time') == pos.get('entryBarTime'):
                    hi = lo = price
                else:
                    hi = bar.get('high', price); lo = bar.get('low', price)
                if is_long:
                    if lo <= pos['sl']:    reason, exit_px = 'SL hit', pos['sl']
                    elif hi >= pos['tp']:  reason, exit_px = 'TP hit', pos['tp']
                else:
                    if hi >= pos['sl']:    reason, exit_px = 'SL hit', pos['sl']
                    elif lo <= pos['tp']:  reason, exit_px = 'TP hit', pos['tp']
                if reason is None:
                    if strat['signal'] == 'CLOSE':             reason = 'EMA exit'   # dual: EMA opposes SuperTrend
                    elif is_long and strat['signal'] == 'SELL':  reason = 'signal reversal'
                    elif (not is_long) and strat['signal'] == 'BUY': reason = 'signal reversal'
            if reason:
                _re_side, _re_slp, _re_tpp, _re_cont = pos['side'], pos.get('slPct'), pos.get('tpPct'), (pos.get('contCount') or 0)
                _delta_bot_close(exit_px, reason, mode)
                _bartime = candles[-1].get('time')
                # Stop & reverse: opposite signal closes then opens the other side.
                if reason == 'signal reversal' and delta_ai_state.get('running') and not delta_ai_state.get('position') and strat['signal'] in ('BUY', 'SELL') and not (cfg.get('emaMode') and _bot_is_ranging(candles, cfg)):
                    _bot_log('[Tick] [delta] {} stop & reverse -> {} @ {}'.format(symbol, strat['signal'], price))
                    _delta_bot_open(strat['signal'], price, strat, mode)
                    if delta_ai_state.get('position'): delta_ai_state['position']['entryBarTime'] = _bartime
                # TP-continuation (TV mode): re-enter SAME side while SuperTrend still
                # backs it. Win-protect: tighter SL (= TP%, 1:1) so banked TPs aren't
                # given back; cap chain depth; skip if the market has gone choppy.
                elif reason == 'TP hit' and not _bot_is_claude(cfg) and _tv_dual_aligned(cfg, symbol, _re_side) and delta_ai_state.get('running') and not delta_ai_state.get('position'):
                    _cont_n = _re_cont + 1
                    _maxc = int(cfg.get('maxCont', 4) or 4)
                    if _cont_n > _maxc:
                        _bot_log('[Tick] [delta] {} TP — continuation cap {} reached, staying flat'.format(symbol, _maxc))
                    elif _bot_is_ranging(candles, cfg):
                        _bot_log('[Tick] [delta] {} TP — skip continuation (ranging)'.format(symbol))
                    else:
                        _cont_sl = float(cfg.get('contSlPct') or _re_tpp or _re_slp or 1.0)
                        _re = {'name': 'tv', 'signal': _re_side, 'score': 10.0,
                               'reason': 'TP re-entry (continuation #{})'.format(_cont_n),
                               'slPct': _cont_sl, 'tpPct': _re_tpp}
                        _bot_log('[Tick] [delta] {} TP re-entry #{} -> {} @ {} (SL {}% TP {}%)'.format(symbol, _cont_n, _re_side, price, _cont_sl, _re_tpp))
                        _delta_bot_open(_re_side, price, _re, mode)
                        if delta_ai_state.get('position'):
                            delta_ai_state['position']['entryBarTime'] = _bartime
                            delta_ai_state['position']['contCount'] = _cont_n
            else:
                _bot_log('[Tick] [delta] {} px={} SL={} TP={} ({} from {}) [{}]'.format(
                    symbol, price, pos.get('sl'), pos.get('tp'), pos['side'], pos['entryPrice'], er_tag))
        else:
            if strat['signal'] in ('BUY', 'SELL') and strat.get('seed'):
                # Manual SuperTrend bias seed (Option D): open immediately at start,
                # bypassing cooldown/quality (the user explicitly chose this entry).
                delta_ai_state.pop('_pending', None)
                _bot_log('[Tick] [delta] {} manual bias seed -> open {} @ {}'.format(symbol, strat['signal'], price))
                _delta_bot_open(strat['signal'], price, strat, mode)
                if delta_ai_state.get('position'): delta_ai_state['position']['entryBarTime'] = candles[-1].get('time')
            elif strat['signal'] in ('BUY', 'SELL'):
                # Re-entry cooldown: avoid whipsaw churn right after an exit
                # (the PAXGUSD signal-reversal losses in log.txt).
                cooldown = int(cfg.get('cooldownSec', 60) or 0)
                last_exit = delta_ai_state.get('last_exit_time') or 0
                if cooldown and (int(_zd_time.time()) - last_exit) < cooldown:
                    _bot_log('[Tick] [delta] {} {} skipped — cooldown {}s after last exit'.format(
                        symbol, strat['signal'], cooldown))
                elif (not _bot_is_claude(cfg)) and _bot_is_ranging(candles, cfg):
                    _bot_defer_entry(delta_ai_state, cfg, strat)   # take it when ER recovers
                    _bot_log('[Tick] [delta] {} {} skipped — ranging (chop filter, ER<{}); deferred until ER recovers'.format(
                        symbol, strat['signal'], cfg.get('minER', 0.28)))
                else:
                    delta_ai_state.pop('_pending', None)
                    ok, qreason = (True, '') if _bot_is_claude(cfg) else _bot_entry_quality(strat['signal'], candles, regime, cfg)
                    if ok:
                        _delta_bot_open(strat['signal'], price, strat, mode)
                        if delta_ai_state.get('position'): delta_ai_state['position']['entryBarTime'] = candles[-1].get('time')
                    else:
                        _bot_log('[Tick] [delta] {} {} skipped — entry quality: {}'.format(
                            symbol, strat['signal'], qreason))
            elif _bot_take_deferred(delta_ai_state, cfg, candles, price, _delta_bot_open, mode):
                _bot_log('[Tick] [delta] {} deferred entry taken — ER recovered ({})'.format(symbol, er_tag))
            else:
                _bot_log('[Tick] [delta] {} price={} HOLD — {} (score {:.1f}) [{}]'.format(symbol, price, strat['reason'], strat['score'], er_tag))

def _delta_bot_loop():
    while True:
        with delta_ai_lock:
            running = delta_ai_state.get('running', False)
            paused  = delta_ai_state.get('paused', False)
        if not running: break
        if not paused:
            # Fast loop (priceTickSec, default 10s): refresh price + check stops.
            # Claude DECISIONS only run every 'tickSec' (the configured bot tick),
            # gated by _decide so API cost is unchanged while price/stops stay live.
            _cfg = delta_ai_state.get('config') or {}
            _now = _zd_time.time()
            _dsec = max(5, int(_cfg.get('tickSec', _BOT_TICK_SEC) or _BOT_TICK_SEC))
            delta_ai_state['_decide'] = (_now - delta_ai_state.get('_last_decision_ts', 0)) >= _dsec
            try: _delta_bot_tick()
            except Exception as e:
                _bot_log('[Tick] ERROR: ' + str(e))
            if delta_ai_state.get('_decide'): delta_ai_state['_last_decision_ts'] = _now
        _bot_gc_tick()
        _zd_time.sleep(max(5, int((delta_ai_state.get('config') or {}).get('priceTickSec', 10) or 10)))

# Need timedelta/timezone for IST log timestamps
import datetime as _tz_module

@app.route('/api/aibot/delta/start', methods=['POST'])
@login_required
def delta_aibot_start():
    data = request.json or {}
    with delta_ai_lock:
        if delta_ai_state.get('running'):
            return jsonify({'success': False, 'error': 'Bot is already running. Stop it first.'}), 400
        delta_ai_state['config'] = {
            'symbol':     (data.get('symbol') or '').upper(),
            'symbols':    [s.strip().upper() for s in (data.get('symbols') or []) if s and str(s).strip()],
            'autoSymbol': bool(data.get('autoSymbol', False)),
            'qty':        int(data.get('qty', 1) or 1),
            'tf':         data.get('tf', '5m'),
            'mode':       data.get('mode', 'paper'),
            'slPct':      float(data.get('slPct', 1.0)),
            'tpPct':      float(data.get('tpPct', 2.0)),
            'maxConsec':  int(data.get('maxConsec', 3) or 3),
            'maxLoss':    float(data.get('maxLoss', 200) or 200),
            'tokens':     bool(data.get('tokens', False)),   # Delta only: trade top-gainer tokens in auto mode
            'capital':    float(data.get('capital') or 0),   # Delta only: auto-size leverage & qty from this
            'leverage':   float(data.get('leverage') or 0),  # Delta only: manual leverage from the panel (0 = default 5)
            'maxProfit':  float(data.get('maxProfit', 0) or 0),
            'minScore':   float(data.get('minScore') if data.get('minScore') is not None else 4.0),
            'scoreBuffer': float(data.get('scoreBuffer') if data.get('scoreBuffer') is not None else 1.0),
            'cooldownSec': int(data.get('cooldownSec', 60) or 0),
            'tickSec':    max(5, int(data.get('tickSec', _BOT_TICK_SEC) or _BOT_TICK_SEC)),
            'qualityFilter': bool(data.get('qualityFilter', True)),
            'avoidRange': bool(data.get('avoidRange', True)),         # skip TV entries in chop (efficiency-ratio filter)
            'minER':      float(data.get('minER', 0.28) or 0.28),     # ranging if efficiency ratio < this
            'maxCont':    int(data.get('maxCont', 4) or 4),           # cap TP-continuation chain depth
            'contSlPct':  float(data.get('contSlPct') or 0),         # tighter SL on continuation legs (0 = use TP%, 1:1)
            'trendGate':  bool(data.get('trendGate', True)),         # only enter WITH the EMA50/200 trend (ma4/ma5 in the SuperTrend alert)
            'trendGateLoose': bool(data.get('trendGateLoose', False)),  # loose = price vs EMA200 only (skip the EMA50>EMA200 condition)
            'maxSeedSlPct': float(data.get('maxSeedSlPct', 2.0) or 2.0),  # cap SL% on manual seed/Open (no 5% panel default)
            'seedRiskFrac': float(data.get('seedRiskFrac', 0.5) or 0.5),  # a seed/manual SL may risk at most this × maxLoss
            'emaMode':    bool(data.get('emaMode', False)),          # 'EMA 5/13' mode: EMA alert is entry+exit, SuperTrend ignored
            'pendingSec': int(data.get('pendingSec') if data.get('pendingSec') is not None else 60),  # chop-skipped entry waits this long for ER to recover (0 = off)
            'includeMM':  bool(data.get('includeMM', False)),
            'includeMMA': bool(data.get('includeMMA', False)),
            'allowedStrategies': [s for s in (data.get('allowedStrategies') if data.get('allowedStrategies') is not None else _BOT_DEFAULT_ALLOWED) if s in _BOT_CONFIGURABLE_ALGOS],
            'model':      (data.get('model') or '').strip(),   # Claude model: haiku|sonnet|opus (blank = env default)
            'tvEnabled':  bool(data.get('tvEnabled', False)),  # weigh TradingView TA + webhook as context
            'tvSymbol':   (data.get('tvSymbol') or '').strip().upper(),
            'api_key':    (data.get('api_key') or '').strip(),
        }
        _c = delta_ai_state['config']
        if not _c['symbol'] and not _c['symbols'] and not _c['autoSymbol'] and not _c.get('tokens'):
            return jsonify({'success': False, 'error': 'Pick a symbol, a watchlist, or enable Auto symbol / Tokens'}), 400
        delta_ai_state['scan_idx']      = 0
        delta_ai_state['position']      = None
        delta_ai_state['trades']        = []
        delta_ai_state['consec_losses'] = 0
        delta_ai_state['last_exit_time'] = 0
        delta_ai_state['log_buffer']    = []
        delta_ai_state['last_tick']     = {}
        delta_ai_state['last_candles']  = []
        delta_ai_state['seedBias']      = _seed_bias_norm(data.get('seedBias'))   # Option D: open in this bias at start
        delta_ai_state['running']       = True
        delta_ai_state['paused']        = False
        t = _threading.Thread(target=_delta_bot_loop, daemon=True, name='delta-aibot')
        delta_ai_state['thread'] = t
        t.start()
    cfg = delta_ai_state['config']
    _bot_log('Delta Bot started SERVER-SIDE in {} mode for {} qty={} TF={}. Tick every {}s — runs even when you close this tab.'.format(
        cfg['mode'].upper(), cfg['symbol'], cfg['qty'], cfg['tf'], _BOT_TICK_SEC))
    _persist_log_line('[DELTA] [{}] BOT START {} qty={} TF={} (server-side)'.format(
        cfg['mode'].upper(), cfg['symbol'], cfg['qty'], cfg['tf']))
    _cfg_line = _bot_cfg_summary(cfg, {'seedBias': delta_ai_state.get('seedBias') or '-'})
    _bot_log('[Config] ' + _cfg_line)
    _persist_log_line('[DELTA] [CONFIG] ' + _cfg_line)
    return jsonify({'success': True, 'message': 'Bot started server-side'})

@app.route('/api/aibot/delta/manual', methods=['POST'])
@login_required
def delta_aibot_manual():
    """Manual Open/Close override: queue a command the running bot executes on its
    next tick (open BUY/SELL at market with the configured SL%/TP%, or close)."""
    data = request.json or {}
    action = (data.get('action') or '').lower()
    side = _seed_bias_norm(data.get('side'))
    if action not in ('open', 'close'):
        return jsonify({'success': False, 'error': 'action must be open or close'}), 400
    if action == 'open' and side not in ('BUY', 'SELL'):
        return jsonify({'success': False, 'error': 'pick Long or Short first'}), 400
    with delta_ai_lock:
        if not delta_ai_state.get('running'):
            return jsonify({'success': False, 'error': 'Start the bot first'}), 400
        delta_ai_state['manualCmd'] = {'action': action, 'side': side}
    _bot_log('[Manual] queued {} {}'.format(action.upper(), side or ''))
    return jsonify({'success': True, 'message': 'Manual {} {} queued — runs on next tick'.format(action, side or '')})

@app.route('/api/aibot/delta/pause', methods=['POST'])
@login_required
def delta_aibot_pause():
    with delta_ai_lock:
        if not delta_ai_state.get('running'):
            return jsonify({'success': False, 'error': 'Bot is not running'}), 400
        delta_ai_state['paused'] = not delta_ai_state.get('paused', False)
        paused = delta_ai_state['paused']
    _bot_log('Delta Bot ' + ('paused' if paused else 'resumed'))
    return jsonify({'success': True, 'paused': paused})

@app.route('/api/aibot/delta/stop', methods=['POST'])
@login_required
def delta_aibot_stop():
    with delta_ai_lock:
        was_running = delta_ai_state.get('running')
        delta_ai_state['running'] = False
        delta_ai_state['paused']  = False
        cfg  = delta_ai_state.get('config') or {}
        mode = cfg.get('mode', 'paper')
        pos  = delta_ai_state.get('position')
        last_price = (delta_ai_state.get('last_tick') or {}).get('price') or (pos.get('entryPrice') if pos else 0)
        if pos:
            _delta_bot_close(last_price, 'bot stop', mode)
    if was_running:
        _bot_log('Delta Bot stopped.')
        _persist_log_line('[DELTA] [{}] BOT STOP'.format(mode.upper()))
    return jsonify({'success': True})

# --- Claude assistant for the Delta bot -------------------------------------
# Config keys Claude / the Apply button is allowed to change at runtime. Safety:
# symbol, qty, mode and api_key are deliberately NOT here — changing those needs
# an explicit restart so a chat message can never silently flip paper->live or
# swap the traded instrument / size.
_DELTA_TUNABLE_KEYS = {
    'slPct': float, 'tpPct': float, 'maxConsec': int, 'maxLoss': float,
    'maxProfit': float, 'minScore': float, 'scoreBuffer': float, 'cooldownSec': int,
    'qualityFilter': bool, 'includeMM': bool, 'includeMMA': bool,
}

def _sanitize_delta_patch(patch):
    """Coerce an incoming config patch to the whitelisted keys/types. Returns
    (clean_patch, rejected_keys)."""
    clean, rejected = {}, []
    for k, v in (patch or {}).items():
        if k not in _DELTA_TUNABLE_KEYS:
            rejected.append(k); continue
        caster = _DELTA_TUNABLE_KEYS[k]
        try:
            if caster is bool:
                clean[k] = v if isinstance(v, bool) else str(v).strip().lower() in ('1','true','yes','on')
            else:
                clean[k] = caster(v)
        except (TypeError, ValueError):
            rejected.append(k)
    return clean, rejected

# Friendly model names chosen in each AI bot panel → Anthropic model IDs.
_CLAUDE_MODEL_IDS = {
    'haiku':  'claude-haiku-4-5-20251001',
    'sonnet': 'claude-sonnet-4-6',
    'opus':   'claude-opus-4-8',
}

def _resolve_claude_model(name):
    """Map a panel model choice (haiku/sonnet/opus) to an Anthropic model ID.
    Accepts a full 'claude-*' id as-is. Falls back to CLAUDE_MODEL env / sonnet."""
    key = (name or '').strip().lower()
    if key in _CLAUDE_MODEL_IDS:
        return _CLAUDE_MODEL_IDS[key]
    if key.startswith('claude-'):
        return key
    return os.environ.get('CLAUDE_MODEL', 'claude-sonnet-4-6').strip() or 'claude-sonnet-4-6'

# ---- Vision: chart-image input for Claude (base64 image content blocks) ------
# A user can upload a TradingView chart (SuperTrend / EMA / PSAR / S-R, multi-TF) in
# the bot chat. We keep the LATEST image per bot in its state dict ('chartImg') and
# feed it to Claude both in chat replies and in the live trade-decision loop, so the
# Claude strategy reads real chart structure on top of the numeric data.
_CHART_MAX_AGE = 3 * 3600   # an uploaded chart stays "current" for 3h

def _parse_data_url(s):
    """'data:image/png;base64,XXXX' -> {'media','data'} or None (size-guarded ~5MB)."""
    m = re.match(r'^data:(image/[A-Za-z0-9.+-]+);base64,(.+)$', (s or '').strip(), re.DOTALL)
    if not m:
        return None
    media, b64 = m.group(1), m.group(2).strip()
    if not b64 or len(b64) > 7_000_000:
        return None
    return {'media': media, 'data': b64}

def _chart_store(state, lock, data_url, note=''):
    """Save the latest uploaded chart on a bot's state. Returns True if stored."""
    img = _parse_data_url(data_url)
    if not img:
        return False
    img['ts'] = int(_zd_time.time())
    img['note'] = str(note or '')[:200]
    with lock:
        state['chartImg'] = img
    return True

def _chart_images_for(state, max_age_sec=_CHART_MAX_AGE):
    """[{'media','data'}] for _call_claude if the bot has a fresh chart, else []."""
    img = state.get('chartImg') if isinstance(state, dict) else None
    if not img or not img.get('data'):
        return []
    if max_age_sec and (int(_zd_time.time()) - int(img.get('ts', 0))) > max_age_sec:
        return []
    return [{'media': img.get('media', 'image/png'), 'data': img['data']}]

def _bot_set_note(state, lock, message):
    """Store the user's latest chat message as a steering note on the bot config so the
    LIVE Claude decision loop factors it in (a bias, a level, 'only longs', 'stay flat').
    Honoured for ~1h (see _claude_trade_signal). Skips the auto chart-upload placeholder."""
    msg = (message or '').strip()
    if not msg or msg.startswith('I uploaded the latest chart'):
        return
    with lock:
        cfg = state.get('config')
        if cfg is not None:
            cfg['userNote'] = {'text': msg[:400], 'ts': int(_zd_time.time())}

def _img_block(img):
    return {'type': 'image', 'source': {'type': 'base64',
            'media_type': img.get('media', 'image/png'), 'data': img.get('data', '')}}

def _attach_images(messages, images):
    """Prepend image content blocks to the LATEST user message (vision input)."""
    blocks = [_img_block(i) for i in (images or []) if i and i.get('data')]
    if not blocks:
        return messages
    msgs = [dict(m) for m in messages]
    idx = next((i for i in range(len(msgs) - 1, -1, -1) if msgs[i].get('role') == 'user'), None)
    if idx is None:
        msgs.append({'role': 'user', 'content': list(blocks)})
        return msgs
    c = msgs[idx].get('content')
    if isinstance(c, list):
        msgs[idx]['content'] = list(blocks) + c
    else:
        msgs[idx]['content'] = list(blocks) + [{'type': 'text', 'text': str(c)}]
    return msgs

def _call_claude(system, messages, max_tokens=1024, model=None, images=None):
    """Call the Anthropic Messages API via stdlib only (no SDK dependency).
    Reads ANTHROPIC_API_KEY from the environment. `model` is a panel choice
    (haiku/sonnet/opus) or full id; None uses the env default. `images` is an
    optional list of {'media','data'} base64 chart blocks (vision). Returns (text, error)."""
    api_key = os.environ.get('ANTHROPIC_API_KEY', '').strip()
    if not api_key:
        return None, 'ANTHROPIC_API_KEY is not set on the server. Add it in your environment (Render → Environment) and redeploy.'
    model = _resolve_claude_model(model)
    if images:
        messages = _attach_images(messages, images)
    import urllib.request as _ur, json as _json
    body = _json.dumps({
        'model': model, 'max_tokens': max_tokens,
        'system': system, 'messages': messages,
    }).encode('utf-8')
    req = _ur.Request('https://api.anthropic.com/v1/messages', data=body, method='POST',
                      headers={'content-type': 'application/json',
                               'x-api-key': api_key,
                               'anthropic-version': '2023-06-01'})
    try:
        with _ur.urlopen(req, timeout=45) as resp:
            data = _json.loads(resp.read().decode('utf-8'))
    except Exception as e:
        detail = ''
        try: detail = e.read().decode('utf-8')   # type: ignore[attr-defined]
        except Exception: pass
        # Surface Anthropic's human-readable reason (e.g. "Your credit balance is
        # too low…") instead of a truncated raw blob.
        msg = ''
        try:
            msg = ((_json.loads(detail) or {}).get('error') or {}).get('message', '')
        except Exception:
            pass
        if msg:
            return None, 'Claude API error: ' + msg
        return None, ('Claude API error: {} {}'.format(e, detail))[:500]
    parts = data.get('content') or []
    text  = ''.join(p.get('text', '') for p in parts if p.get('type') == 'text')
    return text, None

# =============================== Telegram (Nifty_MV_bot) ======================
# Sends a daily pre-market brief (Claude + live TradingView TA) and forwards bot
# events from log.txt to a Telegram chat. Token from env TELEGRAM_BOT_TOKEN or UI;
# chat_id from env TELEGRAM_CHAT_ID or UI. Threads idle until a toggle is on.
# The 5 scheduled alerts (the 6th, 'events', is realtime log forwarding). Each has its
# own on/off + HH:MM time (+ universe for the stock scans). 'masterOn' is the global
# kill switch — when off, NOTHING fires.
def _tg_default_alerts():
    return {
        'brief':      {'on': False, 'time': '08:30'},
        'intraday':   {'on': False, 'time': '09:30', 'universe': 'NIFTY500'},
        'fno':        {'on': False, 'time': '09:30', 'universe': 'FNO'},
        'positional': {'on': False, 'time': '09:30', 'universe': 'NIFTY500'},
        'momentum':   {'on': False, 'time': '09:30', 'universe': 'NIFTY500'},
    }
_TG_ALERT_LABELS = {'brief': 'Nifty morning brief', 'intraday': 'Intraday stocks',
                    'fno': 'Intraday F&O stocks', 'positional': 'Positional stocks',
                    'momentum': 'Momentum (3-month)'}

_TG_STATE = {
    'token':   os.environ.get('TELEGRAM_BOT_TOKEN', '').strip(),
    'chat_id': os.environ.get('TELEGRAM_CHAT_ID', '').strip(),
    'events': False, 'masterOn': True, 'alerts': _tg_default_alerts(),
    '_last': {}, 'started': False,
    # Live index-analysis engine (Nifty + Sensex every 15m in market hours).
    'analysis_cfg': {'on': False, 'start': '09:30', 'end': '15:30', 'everyMin': 15},
    'analysis': {},
}
_TG_LOCK = _threading.Lock()
_TG_QUEUE = []
# Persist token / chat_id / toggles / per-alert schedule so they're reused on every
# restart (gitignored — the token is a secret). File overrides env defaults.
# IMPORTANT: store it on the SAME persistent volume as the SQLite DB (Render mounts
# /data). The repo/app dir is EPHEMERAL on Render — writing there means the config
# (events + per-alert on/off flags) is wiped on every restart, which silently turns
# OFF scheduled alerts and event-forwarding while manual sends (token from env) keep
# working. Fall back to the repo dir for local dev where there's no DB volume.
def _tg_cfg_path():
    db = (os.environ.get('DB_PATH', '') or '').strip()
    d = os.path.dirname(db) if db else ''
    if d and os.path.isdir(d):
        return os.path.join(d, 'telegram_config.json')
    return os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'telegram_config.json')
_TG_CFG_PATH = _tg_cfg_path()

def _tg_save():
    try:
        import json as _j
        with open(_TG_CFG_PATH, 'w', encoding='utf-8') as f:
            _j.dump({k: _TG_STATE.get(k) for k in ('token', 'chat_id', 'events', 'masterOn', 'alerts', 'analysis_cfg')}, f)
    except Exception:
        pass

def _tg_load():
    try:
        import json as _j
        with open(_TG_CFG_PATH, encoding='utf-8') as f:
            d = _j.load(f) or {}
    except Exception:
        return
    for k in ('token', 'chat_id'):
        if d.get(k):
            _TG_STATE[k] = d[k]
    for k in ('events', 'masterOn'):
        if isinstance(d.get(k), bool):
            _TG_STATE[k] = d[k]
    saved = d.get('alerts') or {}
    if isinstance(saved, dict):
        merged = _tg_default_alerts()
        for key, cfg in merged.items():
            if isinstance(saved.get(key), dict):
                cfg.update({kk: vv for kk, vv in saved[key].items() if kk in ('on', 'time', 'universe')})
        _TG_STATE['alerts'] = merged
    ac = d.get('analysis_cfg')
    if isinstance(ac, dict):
        cur = _TG_STATE.get('analysis_cfg') or {}
        cur.update({k: v for k, v in ac.items() if k in ('on', 'start', 'end', 'everyMin')})
        _TG_STATE['analysis_cfg'] = cur
_TG_MARKETS = [
    ('NIFTY 50', 'NSE:NIFTY'), ('SENSEX', 'BSE:SENSEX'), ('Bank Nifty', 'NSE:BANKNIFTY'),
    ('Crude Oil MCX', 'MCX:CRUDEOIL1!'), ('Gold MCX', 'MCX:GOLD1!'),
    ('Gold (global)', 'TVC:GOLD'), ('WTI crude', 'TVC:USOIL'),
    ('US Dollar idx', 'TVC:DXY'), ('Nasdaq 100', 'NASDAQ:NDX'), ('S&P 500', 'SP:SPX'),
]

def _tg_now_ist():
    from datetime import datetime as _dt, timezone as _tzc, timedelta as _tdc
    return _dt.now(_tzc(_tdc(seconds=IST_OFFSET)))

def _now_ist_str():
    return _tg_now_ist().strftime('%Y-%m-%d %H:%M IST')

def _tg_api(method, params, token=None):
    token = (token or _TG_STATE.get('token') or '').strip()
    if not token:
        return None, 'No Telegram token set.'
    import urllib.request as _ur, urllib.parse as _up, json as _j
    url = 'https://api.telegram.org/bot{}/{}'.format(token, method)
    try:
        with _ur.urlopen(_ur.Request(url, data=_up.urlencode(params).encode('utf-8')), timeout=20) as resp:
            return _j.loads(resp.read().decode('utf-8')), None
    except Exception as e:
        detail = ''
        try: detail = e.read().decode('utf-8')   # type: ignore[attr-defined]
        except Exception: pass
        return None, ('Telegram error: {} {}'.format(e, detail))[:300]

def _tg_send(text, token=None, chat_id=None):
    chat_id = (chat_id or _TG_STATE.get('chat_id') or '').strip()
    if not chat_id:
        return False, 'No chat_id — set it (or click Detect chat id after messaging the bot).'
    ok_any, err = False, None
    for i in range(0, len(text) or 1, 3800):                       # Telegram caps at 4096 chars/msg
        res, e = _tg_api('sendMessage', {'chat_id': chat_id, 'text': text[i:i + 3800],
                                         'disable_web_page_preview': 'true'}, token)
        if res and res.get('ok'): ok_any = True
        else: err = e or (res or {}).get('description') or 'send failed'
    return ok_any, err

def _tg_detect_chat(token=None):
    res, e = _tg_api('getUpdates', {'limit': '8'}, token)
    if e: return None, e
    for upd in reversed(res.get('result') or []):
        chat = ((upd.get('message') or upd.get('channel_post') or upd.get('my_chat_member') or {}).get('chat') or {})
        if chat.get('id') is not None:
            return str(chat['id']), None
    return None, 'No recent messages. Send any message to your bot in Telegram first, then retry.'

def _tg_market_snapshot():
    rows = []
    for name, sym in _TG_MARKETS:
        ta = _tv_fetch_ta(sym, '1D') or _tv_fetch_ta(sym, '')
        if ta and ta.get('close') is not None:
            rows.append('{}: close={} rating={} RSI={} MACDh={} ADX={}'.format(
                name, ta.get('close'), ta.get('rating'), ta.get('rsi'), ta.get('macdHist'), ta.get('adx')))
        else:
            rows.append('{}: (no data)'.format(name))
    return '\n'.join(rows)

def _tg_morning_text():
    snap = _tg_market_snapshot()
    system = ("You are an experienced Indian-markets analyst writing a concise pre-market brief for an "
              "intraday trader. Use ONLY the daily technical snapshot provided (close, TradingView rating, "
              "RSI, MACD histogram, ADX). Be specific and practical, not generic. Sections, in this order:\n"
              "1) Global cues (US indices, DXY, WTI crude, gold) in 2-3 lines.\n"
              "2) Nifty & Sensex view + intraday bias (up/down/range).\n"
              "3) Key levels — for NIFTY, SENSEX, CRUDEOIL, GOLD give Support 1/2 and Resistance 1/2 "
              "estimated from close + momentum (note they are technical estimates).\n"
              "4) Today's trade idea: 1-2 actionable setups with entry zone, stop and target.\n"
              "Keep under 320 words. Plain text only (no markdown headers/bold). A few emojis are fine.")
    user = "Daily snapshot ({}):\n{}\n\nWrite the brief.".format(_now_ist_str(), snap)
    text, err = _call_claude(system, [{'role': 'user', 'content': user}], max_tokens=1100, model='sonnet')
    if err:
        return 'Nifty_MV morning brief — ' + _now_ist_str() + '\n\n(AI analysis unavailable: ' + err + ')\n\nSnapshot:\n' + snap
    return 'Nifty_MV morning brief — ' + _now_ist_str() + '\n\n' + (text or '').strip()

