def _tv_log_alert(sym, entry):
    """Log a received TradingView alert (the WHOLE payload) to log.txt and mirror it
    into any RUNNING bot whose symbol matches, so it shows in that panel's log."""
    price = entry.get('price')
    pstr = (' price=' + str(price)) if (price not in (None, '')) else ''
    fstr = ''.join(' {}={}'.format(k, v) for k, v in (entry.get('fields') or {}).items())
    note = entry.get('note') or ''
    nstr = (' note="' + note + '"') if note else ''
    indicator = entry.get('indicator') or ''
    istr = (' [' + indicator + ']') if indicator else ''
    tstr = ' (TEST — not traded)' if entry.get('test') else ''
    line = '[TV-ALERT] {} {}{}{}{}{}{}'.format(sym, entry.get('signal') or '?', pstr, fstr, nstr, istr, tstr)
    _persist_log_line(line)
    for state, logfn in ((delta_ai_state, _bot_log), (zd_ai_state, _zd_log),
                         (mt_ai_state, _mt_log), (zo_ai_state, _zo_log)):
        try:
            if not state.get('running'):
                continue
            cfg = state.get('config') or {}
            keys = set()
            for k in (cfg.get('symbol'), cfg.get('baseSymbol')):
                if k: keys.add(str(k).upper())
            tv = (cfg.get('tvSymbol') or '').upper()
            if tv: keys.add(tv.split(':')[-1])
            for leg in (state.get('legs') or []):
                if leg.get('symbol'): keys.add(str(leg['symbol']).upper())
            roots = {_tv_root(k) for k in keys}
            if sym in keys or _tv_root(sym) in roots:
                logfn(line)
        except Exception:
            pass

def _tv_norm_signal(raw):
    """Normalise a TradingView signal value to 'BUY'/'SELL'/'' (unknown).
    Unresolved placeholders like {{strategy.order.action}} -> '' (not a signal)."""
    s = (raw or '').strip().upper()
    if not s or '{{' in s or '}}' in s:
        return ''
    if s in ('BUY', 'LONG', 'B', 'BULL', 'BULLISH', 'ENTRYLONG', 'LONGENTRY'):
        return 'BUY'
    if s in ('SELL', 'SHORT', 'S', 'BEAR', 'BEARISH', 'ENTRYSHORT', 'SHORTENTRY'):
        return 'SELL'
    return ''

def _seed_bias_norm(v):
    """Normalise a manual SuperTrend bias choice -> 'BUY'/'SELL'/'' (Option D).
    Accepts long/buy/bull -> BUY, short/sell/bear -> SELL; anything else clears it."""
    s = (str(v or '')).strip().upper()
    if s in ('BUY', 'LONG', 'BULL', 'UP'):   return 'BUY'
    if s in ('SELL', 'SHORT', 'BEAR', 'DOWN'): return 'SELL'
    return ''

def _tv_recover_signal(text):
    """Last-resort: scan free text for a buy/sell word (e.g. a strategy comment)."""
    t = (text or '').upper()
    if '{{' in t:                        # still an unresolved placeholder
        return ''
    has_buy  = any(w in t for w in (' BUY', 'LONG', 'BULL'))
    has_sell = any(w in t for w in ('SELL', 'SHORT', 'BEAR'))
    if has_buy and not has_sell:  return 'BUY'
    if has_sell and not has_buy:  return 'SELL'
    return ''

def _tv_root(sym):
    """Normalise a symbol to its instrument ROOT so a TradingView alert symbol
    matches the bot's tradingsymbol even when they differ by exchange/contract:
      BITSTAMP:BTCUSD -> BTCUSD ;  PAXGUSD.P -> PAXGUSD ;  GOLDTEN1! -> GOLDTEN ;
      GOLDTEN26JUNFUT -> GOLDTEN ;  NIFTY26JUN24000CE -> NIFTY..(left as-is mostly)."""
    import re as _re2
    s = (sym or '').upper().strip()
    if ':' in s:
        s = s.split(':')[-1]
    s = _re2.sub(r'\.PERP$', '', s)
    s = _re2.sub(r'\.P$', '', s)
    s = _re2.sub(r'\d+!$', '', s)                 # continuous futures  GOLDTEN1! -> GOLDTEN
    s = _re2.sub(r'\d{2}[A-Z]{3}FUT$', '', s)     # Kite futures        GOLDTEN26JUNFUT -> GOLDTEN
    return s

def _tv_alert_for(cfg, symbol, base='', skip_test=False):
    """Newest TradingView webhook alert dict that matches a bot's symbol. Matches
    on the exact key OR the normalised instrument root (so PAXGUSD.P matches a
    PAXGUSD bot and GOLDTEN1! matches GOLDTEN26JUNFUT). `skip_test` drops manual
    Test-button alerts so they never trade (only real TradingView alerts do).
    None if nothing matches."""
    keys = set()
    for k in (symbol, (cfg.get('tvSymbol') or '').split(':')[-1], base):
        if k: keys.add(str(k).upper().strip())
    roots = {_tv_root(k) for k in keys}
    roots.discard('')
    best = None
    for k, v in _TV_WEBHOOK.items():
        if skip_test and v.get('test'):
            continue
        ku = str(k).upper()
        if ku in keys or _tv_root(ku) in roots:
            if best is None or int(v.get('ts', 0)) >= int(best.get('ts', 0)):
                best = v
    return best

def _tv_num(v):
    """Parse a numeric alert field; None for blank/null/NaN/non-number. Tolerant of
    stray wrappers users add — braces and a % sign — so "{0.25}" / "0.25%" -> 0.25."""
    if v is None:
        return None
    s = str(v).strip().strip('{}').strip().rstrip('%').strip()
    if s in ('', 'null', 'NULL', 'NaN', 'nan', 'none', 'None'):
        return None
    try:
        f = float(s)
        return None if f != f else f
    except (TypeError, ValueError):
        return None

def _tv_apply_sltp(out, wh, levels=True):
    """Derive the trade's SL/TP from the alert. Priority:
      1) slPct/tpPct (percent) — used directly;
      2) sl/tp (absolute price) — converted to % from the alert price;
      3) STRUCTURE: support/resistance levels (psar, rangeTop, rangeBottom, or
         generic support/resistance) — for a BUY, SL = nearest support BELOW price
         and TP = nearest resistance ABOVE; mirrored for a SELL.
    `levels=False` (option legs) skips 2/3 since those are underlying prices, not
    premium. Falls back to panel defaults when nothing usable is present."""
    f = {str(k).lower(): v for k, v in (wh.get('fields') or {}).items()}
    slp = _tv_num(f.get('slpct')); tpp = _tv_num(f.get('tppct'))
    if slp and slp > 0: out['slPct'] = min(90.0, slp)
    if tpp and tpp > 0: out['tpPct'] = min(90.0, tpp)
    if not levels:
        return out
    price = _tv_num(wh.get('price'))
    if not price or price <= 0:
        return out
    sl_abs = _tv_num(f.get('sl')); tp_abs = _tv_num(f.get('tp'))
    side = out.get('signal')
    if side in ('BUY', 'SELL') and (sl_abs is None or tp_abs is None):
        pool = [_tv_num(f.get(k)) for k in ('psar', 'rangetop', 'rangebottom', 'support', 'resistance')]
        supports    = [x for x in pool if x and x < price]
        resistances = [x for x in pool if x and x > price]
        if side == 'BUY':
            if sl_abs is None and supports:    sl_abs = max(supports)     # nearest support below
            if tp_abs is None and resistances: tp_abs = min(resistances)  # nearest resistance above
        else:
            if sl_abs is None and resistances: sl_abs = min(resistances)  # nearest resistance above
            if tp_abs is None and supports:    tp_abs = max(supports)      # nearest support below
    if 'slPct' not in out and sl_abs: out['slPct'] = min(90.0, abs(price - sl_abs) / price * 100.0)
    if 'tpPct' not in out and tp_abs: out['tpPct'] = min(90.0, abs(price - tp_abs) / price * 100.0)
    return out

def _tv_ind_for(cfg, symbol, base=''):
    """Latest SuperTrend + EMA alerts for a bot's instrument ROOT, for the dual
    state machine. Returns {'SUPERTREND': {...}, 'EMA': {...}} (either may be absent)."""
    roots = set()
    for k in (symbol, (cfg.get('tvSymbol') or '').split(':')[-1], base):
        if k:
            roots.add(_tv_root(str(k)))
    roots.discard('')
    out = {}
    best_ts = {}
    for root, inds in _TV_IND.items():
        if root not in roots:
            continue
        for ind, entry in inds.items():
            if entry.get('ts', 0) >= best_ts.get(ind, -1):
                best_ts[ind] = entry.get('ts', 0); out[ind] = entry
    return out

def _tv_dual_active(cfg, symbol, base=''):
    """True when a SuperTrend and/or EMA alert exists for this bot's symbol — i.e.
    the dual SuperTrend(primary, entry) + EMA(secondary, exit) machine drives trading."""
    inds = _tv_ind_for(cfg, symbol, base)
    return ('SUPERTREND' in inds) or ('EMA' in inds)

def _tv_dual_aligned(cfg, symbol, side, base=''):
    """True when the PRIMARY (SuperTrend) bias still backs `side` ('BUY'/'SELL').
    Gates TP-continuation: keep re-entering only while SuperTrend still agrees.
    EMA is exit-only and does NOT gate continuation (an opposing EMA would already
    have closed the position via its own exit)."""
    if cfg.get('emaMode'):
        return True   # EMA-only mode: SuperTrend is ignored, never blocks continuation
    inds = _tv_ind_for(cfg, symbol, base)
    st = inds.get('SUPERTREND')
    if not st:
        return True   # not in dual mode -> don't block continuation
    return st.get('signal') == side

def _tv_trend_gate_ok(st, side, cfg=None, price=None):
    """Higher-trend filter (EMA50/200): only enter WITH the slow trend. Reads ma4
    (EMA50) and ma5 (EMA200) from the SuperTrend alert `st`; `price` overrides the
    compare price (EMA mode passes the EMA-alert price, since EMA50/200 come from the
    SuperTrend alert). Two modes via trendGateLoose:
      strict: BUY needs price > EMA200 AND EMA50 > EMA200 (mirror for SELL)
      loose : BUY needs price > EMA200 only               (mirror for SELL)
    Returns (ok, reason). Passes when EMA200/price are missing (can't judge) or
    trendGate=False."""
    cfg = cfg or {}
    if not cfg.get('trendGate', True):
        return True, ''
    f = {str(k).lower(): v for k, v in ((st or {}).get('fields') or {}).items()}
    ema50  = _tv_num(f.get('ma4'))
    ema200 = _tv_num(f.get('ma5'))
    px = _tv_num(price) if price is not None else _tv_num((st or {}).get('price'))
    if not ema200 or not px:
        return True, ''                      # need EMA200 + a price to judge
    loose = bool(cfg.get('trendGateLoose'))
    if side == 'BUY':
        ok = (px > ema200) and (loose or not ema50 or ema50 > ema200)
        return ok, 'counter-trend (below EMA200)'
    ok = (px < ema200) and (loose or not ema50 or ema50 < ema200)
    return ok, 'counter-trend (above EMA200)'

def _seed_sltp(cfg, symbol):
    """SL/TP% for a manual seed / manual Open. Prefer the latest SuperTrend alert's
    slPct/tpPct so the first trade is sized like a real entry; else the panel's — but
    CAP the SL at maxSeedSlPct (default 2%) so a stale panel default (Delta defaults to
    5%) can't open an oversized stop. Fixes the SOL seed that opened with SL=5% because
    no SuperTrend alert existed yet. In EMA-only mode the seed reads the EMA alert."""
    inds = _tv_ind_for(cfg, symbol)
    src = inds.get('EMA') if cfg.get('emaMode') else inds.get('SUPERTREND')
    f = {str(k).lower(): v for k, v in ((src or {}).get('fields') or {}).items()}
    slp = _tv_num(f.get('slpct'))
    tpp = _tv_num(f.get('tppct'))
    slp = slp if (slp and slp > 0) else float(cfg.get('slPct') or 1.0)
    tpp = tpp if (tpp and tpp > 0) else float(cfg.get('tpPct') or 0.4)
    cap = float(cfg.get('maxSeedSlPct', 2.0) or 2.0)
    # Risk cap: a seed/manual SL may risk at most seedRiskFrac × maxLoss. With Delta's
    # capital×leverage sizing, loss at SL ≈ slPct/100 × capital × leverage, so
    # slPct ≤ frac×maxLoss / (capital×lev) × 100. (2% × 25x × $100 = $50 = a whole day.)
    capital = float(cfg.get('capital') or 0); lev = float(cfg.get('leverage') or 0)
    maxloss = float(cfg.get('maxLoss') or 0); frac = float(cfg.get('seedRiskFrac', 0.5) or 0.5)
    if capital > 0 and lev > 0 and maxloss > 0:
        cap = min(cap, (frac * maxloss) / (capital * lev) * 100.0)
    return {'slPct': min(max(slp, 0.05), max(cap, 0.05)), 'tpPct': max(tpp, 0.05)}

def _tv_dual_signal(state, cfg, symbol, inds):
    """Dual-indicator logic — SuperTrend is PRIMARY (the only thing that OPENS a
    position); EMA 5/13 is SECONDARY (exit only, never opens):

      * SuperTrend alert  -> ENTRY. Open in its direction when flat; reaffirm when
        already on that side. (No position is ever opened without SuperTrend.)
      * EMA alert         -> EXIT. When holding and EMA prints the OPPOSITE side,
        CLOSE to flat. EMA never opens and never reverses.
      * SuperTrend flip while holding the opposite side does NOT force an exit while
        an EMA exists (exits are EMA's job); for a SuperTrend-only symbol it reverses
        so there is still a way out.
      * TP-continuation (handled in the tick) re-enters the SAME side on TP while
        SuperTrend still backs it.

    Edge-triggered: acts once on the newest unacted ST/EMA alert. SL/TP for opens
    come from the SuperTrend alert (slPct/tpPct/structure)."""
    st = inds.get('SUPERTREND'); ema = inds.get('EMA')
    pos = state.get('position')
    cur = pos.get('side') if pos else None

    st_dir = st.get('signal') if st else None
    st_ts  = int(st.get('ts', 0)) if st else 0
    ema_dir = ema.get('signal') if ema else None
    ema_ts  = int(ema.get('ts', 0)) if ema else 0
    acted = state.get('_tv_acted_ts', 0)

    # Newest UNACTED alert wins. EMA may act on its own as an EXIT (even with no
    # SuperTrend stored, so manual/seed/continuation positions are always protected);
    # only an ENTRY requires SuperTrend.
    best = None
    if st_dir in ('BUY', 'SELL') and st_ts > acted:
        best = (st_ts, 'ST', st_dir)
    if ema_dir in ('BUY', 'SELL') and ema_ts > acted and (best is None or ema_ts > best[0]):
        best = (ema_ts, 'EMA', ema_dir)

    align = 'ST {}{}'.format(st_dir or '—', (' / EMA ' + ema_dir) if ema_dir else '')
    if best is None:
        _st = ('holding ' + cur) if cur else 'flat'
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'TV dual: {} ({})'.format(_st, align)}

    ts, src, sdir = best
    state['_tv_acted_ts'] = ts

    if src == 'EMA':
        # SECONDARY = EMA, EXIT ONLY — works with or without a SuperTrend stored,
        # so a manual/seed/continuation position still gets the fast EMA exit.
        if cur and cur != ema_dir:
            return {'name': 'tv', 'signal': 'CLOSE', 'score': 10.0,
                    'reason': 'TV dual: EMA {} opposes {} -> exit ({})'.format(ema_dir, cur, align)}
        _st = ('holding ' + cur) if cur else 'flat'
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'TV dual: {} (EMA {} — exit-only)'.format(_st, ema_dir)}

    if src == 'ST':
        # PRIMARY = entry only. Open from flat; reaffirm when already on-side.
        if cur is None:
            ok, why = _tv_trend_gate_ok(st, st_dir, cfg)
            if not ok:
                return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0,
                        'reason': 'TV dual: skip {} — {}'.format(st_dir, why)}
            out = {'name': 'tv', 'signal': st_dir, 'score': 10.0,
                   'reason': 'TV dual: open {} (SuperTrend, trend-aligned)'.format(st_dir)}
            return _tv_apply_sltp(out, {'price': st.get('price'), 'fields': st.get('fields') or {}})
        if cur == st_dir:
            return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'TV dual: holding {} (SuperTrend reaffirm)'.format(cur)}
        # holding opposite to a flipped SuperTrend
        if ema is None:
            # SuperTrend-only symbol — no EMA to exit, so the flip reverses.
            out = {'name': 'tv', 'signal': st_dir, 'score': 10.0,
                   'reason': 'TV dual: reverse {} (SuperTrend, no EMA)'.format(st_dir)}
            return _tv_apply_sltp(out, {'price': st.get('price'), 'fields': st.get('fields') or {}})
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0,
                'reason': 'TV dual: SuperTrend flipped {} — exit is EMA-only, holding {}'.format(st_dir, cur)}

    # unreachable (src is always EMA or ST)
    return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'TV dual: hold'}

def _tv_ema_signal(state, cfg, symbol):
    """EMA-ONLY mode (emaMode / the 'EMA 5/13' checkbox): the EMA 5/13 alert is BOTH
    entry and exit. Edge-triggered on the newest EMA alert:
      flat + BUY/SELL  -> OPEN that side
      holding opposite -> REVERSE (close + open the other side)
      holding same     -> hold (reaffirm)
    Trend gate (when on): the entry direction must agree with EMA50/200 read from the
    SuperTrend alert (ma4/ma5); a counter-trend OPEN is skipped, a counter-trend
    REVERSE just EXITS (no new counter-trend position). strict vs loose via
    trendGateLoose. Exits: TP hit (-> continuation, capped by maxCont), opposite EMA,
    panel SL backstop. SL/TP from the EMA alert (else panel), SL capped at maxSeedSlPct."""
    inds = _tv_ind_for(cfg, symbol)
    ema = inds.get('EMA')
    pos = state.get('position')
    cur = pos.get('side') if pos else None
    if not ema or ema.get('signal') not in ('BUY', 'SELL'):
        _st = ('holding ' + cur) if cur else 'flat'
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'EMA mode: {} (waiting for EMA alert)'.format(_st)}
    ema_dir = ema.get('signal'); ema_ts = int(ema.get('ts', 0))
    acted = state.get('_tv_acted_ts', 0)
    if ema_ts <= acted or cur == ema_dir:
        _st = ('holding ' + cur) if cur else 'flat'
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'EMA mode: {} (EMA {})'.format(_st, ema_dir)}
    state['_tv_acted_ts'] = ema_ts
    # Trend gate: EMA50/200 from the SuperTrend alert, price from this EMA alert.
    ok, why = _tv_trend_gate_ok(inds.get('SUPERTREND'), ema_dir, cfg, price=ema.get('price'))
    if not ok:
        if cur:   # holding -> exit, but don't open the counter-trend side
            return {'name': 'tv', 'signal': 'CLOSE', 'score': 10.0,
                    'reason': 'EMA mode: exit {} — new {} is {}'.format(cur, ema_dir, why)}
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'EMA mode: skip {} — {}'.format(ema_dir, why)}
    out = {'name': 'tv', 'signal': ema_dir, 'score': 10.0,
           'reason': 'EMA mode: {} {} (EMA 5/13, trend-aligned)'.format('reverse' if cur else 'open', ema_dir)}
    f = {str(k).lower(): v for k, v in (ema.get('fields') or {}).items()}
    slp = _tv_num(f.get('slpct')); tpp = _tv_num(f.get('tppct'))
    slp = slp if (slp and slp > 0) else float(cfg.get('slPct') or 1.0)
    tpp = tpp if (tpp and tpp > 0) else float(cfg.get('tpPct') or 0.4)
    cap = float(cfg.get('maxSeedSlPct', 2.0) or 2.0)
    out['slPct'] = min(max(slp, 0.05), cap); out['tpPct'] = max(tpp, 0.05)
    return out

def _tv_alert_signal(state, cfg, symbol):
    """TV-ONLY mode (Claude AI not selected): trade directly off the latest UNACTED
    TradingView alert. BUY/LONG -> BUY, SELL/SHORT -> SELL. Acts once per alert.
    Uses sl/tp/slPct/tpPct from the alert when present (else panel defaults).
    When a SuperTrend and/or EMA alert exists for the symbol, the dual state machine
    (SuperTrend = primary/entry, EMA = secondary/exit-only) takes over instead — an
    EMA alert alone never opens a position (it waits for SuperTrend)."""
    if not cfg.get('tvEnabled'):
        return {'name': 'wait', 'signal': 'HOLD', 'score': 0.0, 'reason': 'Select Claude AI or enable TradingView to trade'}
    # Option D — manual SuperTrend bias seed: open ONCE at bot start in the chosen
    # direction, so the first entry fires immediately instead of waiting for a flip.
    seed = state.get('seedBias')
    if seed in ('BUY', 'SELL'):
        state.pop('seedBias', None)                  # consume once, whatever happens
        if not state.get('position'):
            # Seed now respects the trend gate: a counter-trend seed is dropped
            # (don't bypass the gate into a wrong-way trade like the -49.5 SOL seed).
            ok, why = _tv_trend_gate_ok(_tv_ind_for(cfg, symbol).get('SUPERTREND'), seed, cfg)
            if not ok:
                return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0,
                        'reason': 'Seed {} dropped — {}'.format(seed, why)}
            out = {'name': 'tv', 'signal': seed, 'score': 10.0, 'seed': True,
                   'reason': 'Manual SuperTrend bias seed: open ' + seed}
            out.update(_seed_sltp(cfg, symbol))   # SL capped by maxSeedSlPct + seedRiskFrac×maxLoss
            return out
    if cfg.get('emaMode'):                          # 'EMA 5/13' checkbox -> EMA is entry+exit, SuperTrend ignored
        return _tv_ema_signal(state, cfg, symbol)
    inds = _tv_ind_for(cfg, symbol)
    if ('SUPERTREND' in inds) or ('EMA' in inds):
        return _tv_dual_signal(state, cfg, symbol, inds)
    wh = _tv_alert_for(cfg, symbol, skip_test=True)   # only real alerts ever trade
    if not wh:
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'TV: waiting for a real alert'}
    raw = (wh.get('signal') or '').upper()
    sig = 'BUY' if raw in ('BUY', 'LONG') else ('SELL' if raw in ('SELL', 'SHORT') else 'HOLD')
    acted = state.get('_tv_acted_ts', 0)
    if sig == 'HOLD' or int(wh.get('ts', 0)) <= acted:
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'TV: last alert ' + (raw or '?') + ' (already acted)'}
    state['_tv_acted_ts'] = int(wh.get('ts', 0))
    ind = (' [' + wh.get('indicator', '') + ']') if wh.get('indicator') else ''
    return _tv_apply_sltp({'name': 'tv', 'signal': sig, 'score': 10.0, 'reason': 'TV alert ' + sig + ind}, wh)

def _tv_alert_leg_signal(leg, cfg):
    """TV-ONLY mode for an options leg: map the UNDERLYING alert to the leg.
    Bullish (BUY) -> long CE / short PE; bearish (SELL) -> long PE / short CE.
    Acts once per alert per leg."""
    if not cfg.get('tvEnabled'):
        return {'name': 'wait', 'signal': 'HOLD', 'score': 0.0, 'reason': 'Select Claude AI or enable TradingView to trade'}
    wh = _tv_alert_for(cfg, leg.get('symbol', ''), base=cfg.get('baseSymbol'), skip_test=True)
    if not wh:
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'TV: waiting for a real alert'}
    raw = (wh.get('signal') or '').upper()
    bull = raw in ('BUY', 'LONG'); bear = raw in ('SELL', 'SHORT')
    if not (bull or bear):
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'TV: ' + (raw or '?')}
    su = (leg.get('symbol') or '').upper()
    otype = 'CE' if su.endswith('CE') else ('PE' if su.endswith('PE') else '')
    if otype == 'PE':
        leg_sig = 'BUY' if bear else 'SELL'
    else:   # CE or unknown -> treat as directional
        leg_sig = 'BUY' if bull else 'SELL'
    acted = leg.get('_tv_acted_ts', 0)
    if int(wh.get('ts', 0)) <= acted:
        return {'name': 'tv', 'signal': 'HOLD', 'score': 0.0, 'reason': 'TV: ' + raw + ' (already acted)'}
    leg['_tv_acted_ts'] = int(wh.get('ts', 0))
    return _tv_apply_sltp({'name': 'tv', 'signal': leg_sig, 'score': 10.0, 'reason': 'TV alert ' + raw + ' -> ' + (otype or 'leg') + ' ' + leg_sig}, wh, levels=False)

@app.route('/api/aibot/tv/webhook', methods=['POST'])
def aibot_tv_webhook():
    """Receives TradingView alert JSON for the user's CUSTOM indicators and stores
    the latest signal per symbol. No login (TradingView can't authenticate) — a
    ?token= guards it. Configure a TradingView alert with webhook URL:
        <origin>/api/aibot/tv/webhook?token=<token>
    and message body e.g. {"symbol":"NIFTY","signal":"BUY","indicator":"MyPine","note":"..."}"""
    if request.args.get('token', '') != _TV_DEFAULT_TOKEN:
        return jsonify({'success': False, 'error': 'bad token'}), 403
    # TradingView sends the alert message as the body with an inconsistent
    # content-type (often text/plain), so parse JSON regardless; fall back to a
    # plain "SYMBOL SIGNAL" text alert.
    data = request.get_json(force=True, silent=True) or {}
    if not data:
        raw = (request.get_data(as_text=True) or '').strip()
        if raw:
            try:
                import json as _j
                data = _j.loads(raw)
            except Exception:
                parts = raw.split()
                if len(parts) >= 2:
                    data = {'symbol': parts[0], 'signal': parts[1]}
    if not isinstance(data, dict):
        data = {}
    sym = (data.get('symbol') or data.get('ticker') or '').upper().strip()
    if ':' in sym:                       # strip exchange prefix: BITSTAMP:BTCUSD -> BTCUSD
        sym = sym.split(':')[-1].strip()
    if not sym:
        return jsonify({'success': False, 'error': 'no symbol'}), 400
    note = str(data.get('note') or data.get('comment') or data.get('message') or '')[:160]
    sig  = _tv_norm_signal(data.get('signal') or data.get('action'))
    if not sig:                          # signal unresolved/blank — try to recover from text
        sig = _tv_norm_signal(note) or _tv_recover_signal(note) or _tv_recover_signal(str(data.get('signal') or ''))
    # Capture every OTHER scalar field the alert sent (RSI, plots, SL, TP, tf …) so
    # Claude can use the full indicator readout, and unresolved {{placeholders}} are skipped.
    _skip = {'symbol', 'ticker', 'signal', 'action', 'price', 'indicator', 'strategy', 'note', 'comment', 'message'}
    fields = {}
    for k, v in data.items():
        if str(k).lower() in _skip:
            continue
        if isinstance(v, bool) or isinstance(v, (int, float)):
            fields[str(k)[:32]] = v
        elif isinstance(v, str) and v and '{{' not in v and v.strip().lower() not in ('null', 'nan', 'na', 'none', '') and len(v) <= 80:
            fields[str(k)[:32]] = v
        if len(fields) >= 24:
            break
    is_test = bool(data.get('test')) or str(data.get('indicator') or '').strip().upper() == 'TEST'
    _TV_WEBHOOK[sym] = {
        'signal':    sig,
        'price':     data.get('price'),
        'indicator': str(data.get('indicator') or data.get('strategy') or '')[:60],
        'note':      note,
        'fields':    fields,
        'test':      is_test,    # Test/Connect button alert — shown & logged, but NEVER traded
        'ts':        int(_zd_time.time()),
    }
    if len(_TV_WEBHOOK) > _TV_WEBHOOK_MAX:
        for k, _v in sorted(_TV_WEBHOOK.items(), key=lambda kv: kv[1]['ts'])[:50]:
            _TV_WEBHOOK.pop(k, None)
    # Dual-indicator state machine: keep the latest SuperTrend / EMA alert per ROOT
    # so the bot can require BOTH to agree (SuperTrend = bias, EMA = entry/exit trigger).
    _ind = str(data.get('indicator') or data.get('strategy') or '').strip().upper()
    if sig and not is_test and _ind in ('SUPERTREND', 'EMA'):
        _TV_IND.setdefault(_tv_root(sym), {})[_ind] = {
            'symbol': sym, 'signal': sig, 'price': data.get('price'),
            'fields': fields, 'ts': _TV_WEBHOOK[sym]['ts'],
        }
    _tv_log_alert(sym, _TV_WEBHOOK[sym])
    # Trend-gate diagnostic: the gate reads ma4(EMA50)/ma5(EMA200) from the SuperTrend
    # alert. If either isn't numeric, the gate fails OPEN (passes everything) — log the
    # RAW values TradingView sent so a bad {{plot_N}} mapping (NaN/blank) is visible.
    if _ind == 'SUPERTREND' and not is_test:
        if _tv_num(data.get('ma4')) is None or _tv_num(data.get('ma5')) is None:
            _persist_log_line('[TV-ALERT] {} trend gate INERT — ma4/ma5 not numeric: ma4={!r} ma5={!r} (check {{{{plot_N}}}} index)'.format(
                sym, data.get('ma4'), data.get('ma5')))
    return jsonify({'success': True})

@app.route('/api/aibot/tv/bias')
@login_required
def aibot_tv_bias():
    """Current SuperTrend (primary) + EMA (secondary) state for a symbol, read from
    the latest stored webhook alerts. Powers the panel's 'Detect current bias' button
    (Option D) so the user can seed the first entry at bot start."""
    symbol = (request.args.get('symbol') or '').strip()
    root = _tv_root(symbol)
    inds = _TV_IND.get(root, {})
    st = inds.get('SUPERTREND'); ema = inds.get('EMA')
    now = int(_zd_time.time())
    def info(e):
        if not e:
            return None
        return {'signal': e.get('signal'), 'price': e.get('price'),
                'ageSec': max(0, now - int(e.get('ts', 0)))}
    return jsonify({'success': True, 'root': root,
                    'bias': (st or {}).get('signal') or '',
                    'superTrend': info(st), 'ema': info(ema)})

@app.route('/api/aibot/tv/peek')
@login_required
def aibot_tv_peek():
    """Live TradingView readout for a panel's small display: TA rating + indicators
    for the symbol/timeframe, plus the latest custom-indicator webhook signal and
    the webhook URL the user pastes into TradingView alerts."""
    broker   = (request.args.get('broker') or 'kite').lower()
    symbol   = request.args.get('symbol', '')
    exchange = request.args.get('exchange', '')
    tf       = request.args.get('tf', '5m')
    tvsym    = request.args.get('tvsymbol', '')
    ctx = _tv_context({'tvEnabled': True, 'tvSymbol': tvsym, 'tf': tf}, broker, symbol, exchange) or {}
    origin = request.host_url.rstrip('/')
    return jsonify({'success': True, 'tv': ctx,
                    'webhookUrl': origin + '/api/aibot/tv/webhook?token=' + _TV_DEFAULT_TOKEN})

def _reset_bot_state(state, lock):
    """Stop the bot and wipe it back to the initial state (position, trades, log,
    config, counters). The running loop exits on the next iteration."""
    with lock:
        state['running'] = False
        state['paused']  = False
        state['position'] = None
        state['legs']     = []
        state['trades']   = []
        state['consec_losses'] = 0
        state['log_buffer']    = []
        state['last_tick']     = {}
        state['last_candles']  = []
        state['config']        = None
        for k in ('_tv_acted_ts', '_decide', '_last_decision_ts', '_mkt_closed_logged',
                  'scan_idx', 'last_exit_time', 'thread', 'seedBias'):
            state.pop(k, None)

