# Indian exchanges only — the Zerodha panel intentionally hides USD/foreign
# symbols (US equities, CME/COMEX/NYMEX futures, FX, crypto) so an order
# can never be routed to something Zerodha can't trade.
_ZD_INR_EXCHANGES = frozenset({'NSE', 'BSE', 'NFO', 'BFO', 'MCX', 'CDS', 'BCD', 'NCO'})

def _is_zd_inr(row):
    return (row.get('exchange') or '').strip().upper() in _ZD_INR_EXCHANGES

# Per-instrument tick size lookup + price quantizer.
# Exchanges enforce minimum tick sizes (MCX CRUDEOILM = 1.00, NSE equity = 0.05,
# NFO options usually 0.05, etc.). Sending a LIMIT or GTT trigger price that
# isn't an exact multiple of the tick gets rejected as
# "INVALID PRICE - NOT AS PER TICKSIZE".
def _get_instrument_tick(symbol, exchange=''):
    """Find the tick_size for a Kite tradingsymbol. Falls back to 0.05 if unknown."""
    sym_u  = (symbol  or '').upper().strip()
    exch_u = (exchange or '').upper().strip()
    if not sym_u:
        return 0.05
    def _try(rows):
        if not rows:
            return None
        match_exact = None
        match_anyexch = None
        for r in rows:
            rsym = (r.get('symbol') or '').upper()
            if rsym != sym_u:
                continue
            try:
                ts = float(r.get('tick_size') or 0)
            except (TypeError, ValueError):
                ts = 0
            if ts <= 0:
                continue
            rexch = (r.get('exchange') or '').upper()
            if exch_u and rexch == exch_u:
                match_exact = ts
                break
            if match_anyexch is None:
                match_anyexch = ts
        return match_exact if match_exact is not None else match_anyexch
    for src in (_load_kite_all_instruments(), _load_csv_instruments()):
        ts = _try(src)
        if ts:
            return ts
    return 0.05

def _quantize_to_tick(price, tick_size):
    """Round `price` to the nearest multiple of `tick_size`."""
    if not tick_size or tick_size <= 0:
        return round(float(price), 2)
    n = round(float(price) / float(tick_size))
    return round(n * float(tick_size), 4)

@app.route('/api/zerodha/instruments/search')
@login_required
def zerodha_instrument_search():
    q   = request.args.get('q', '').strip().upper()
    seg = request.args.get('seg', '').strip()       # optional filter: NIFTY50, BANKNIFTY, etc.
    # Drop non-INR entries (USOIL/XAUUSD/BTC/etc.) from the curated list
    results = [r for r in _ZD_INSTRUMENTS if _is_zd_inr(r)]
    # Special virtual segment for OPTIONS tab
    if seg == 'OPTIONS':
        results = [r for r in results if 'options' in r.get('tags', '').lower()]
    elif seg:
        results = [r for r in results if r['seg'] == seg]
    if q:
        results = [r for r in results if
            q in r['symbol'] or
            q in r['name'].upper() or
            q in r.get('tags', '').upper() or
            q in r['type'].upper() or
            q in r['exchange'].upper()
        ]
    # On the "All" tab with a query, also pull matches from the full Kite instruments
    # dump (instruments.csv) so any tradingsymbol Kite knows about can be found here.
    # Curated entries above keep priority (added first, deduped by symbol).
    if seg == '' and q:
        seen = {r['symbol'].upper() for r in results}
        for r in _load_csv_instruments():
            sym = r['symbol'].upper()
            if sym in seen:
                continue
            if (q in sym
                or q in r['name'].upper()
                or q in r['exchange'].upper()
                or q in r['type'].upper()
                or q in r['segment'].upper()):
                results.append({
                    'symbol':   r['symbol'],
                    'name':     r['name'],
                    'exchange': r['exchange'],
                    'type':     r['type'] or r['segment'],
                    'seg':      r['seg'],
                    'tags':     '',
                })
                seen.add(sym)
                if len(results) >= 200:
                    break
        return jsonify({'success': True, 'results': results[:200]})
    return jsonify({'success': True, 'results': results[:50]})

# ---- Zerodha NFO instruments cache ----
import csv as _csv, io as _io, time as _zd_time, urllib.request as _zd_urllib
_ZD_NFO_CACHE = {'ts': 0, 'data': []}
_ZD_NFO_TTL   = 3600  # 1 hour

def _load_nfo_instruments():
    now = _zd_time.time()
    if now - _ZD_NFO_CACHE['ts'] < _ZD_NFO_TTL and _ZD_NFO_CACHE['data']:
        return _ZD_NFO_CACHE['data']
    try:
        req = _zd_urllib.Request(
            'https://api.kite.trade/instruments/NFO',
            headers={'User-Agent': 'Mozilla/5.0'}
        )
        with _kite_urlopen(req, timeout=20) as resp:
            content = resp.read().decode('utf-8')
        reader = _csv.DictReader(_io.StringIO(content))
        rows = []
        for row in reader:
            itype = row.get('instrument_type', '')
            if itype not in ('CE', 'PE'):
                continue
            expiry_raw = row.get('expiry', '')
            try:
                exp_dt     = datetime.strptime(expiry_raw, '%Y-%m-%d')
                expiry_short = exp_dt.strftime('%d%b%y').upper()
            except Exception:
                expiry_short = expiry_raw
            rows.append({
                'symbol':       row.get('tradingsymbol', ''),
                'name':         row.get('name', ''),
                'expiry':       expiry_raw,
                'expiry_short': expiry_short,
                'strike':       float(row.get('strike') or 0),
                'type':         itype,
                'lot_size':     row.get('lot_size', ''),
                'exchange':     'NFO',
                'seg':          'OPTIONS',
                'tags':         f"options fno derivatives {row.get('name','').lower()}"
            })
        _ZD_NFO_CACHE['ts']   = now
        _ZD_NFO_CACHE['data'] = rows
        return rows
    except Exception:
        return _ZD_NFO_CACHE.get('data', [])

